-- Schweiz
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Schweiz$t$, $t$schweiz$t$, $t$Schweiz$t$, $t$Mitteleuropa$t$, $t$Europa$t$, $t$/images/destinations/schweiz-hero.jpg$t$, $t$Alpenland der Superlative mit dem Matterhorn, dem Jungfraujoch, glasklaren Seen, malerischen Städten und den schönsten Panoramazügen der Welt.$t$, $t$Die Schweiz ist ein Naturparadies der Superlative und steht wie kein anderes Land für die Alpen. Majestätische Gipfel wie das ikonische Matterhorn bei Zermatt und das „Top of Europe“ Jungfraujoch ziehen Bergliebhaber aus aller Welt an. Das Berner Oberland rund um Interlaken, Grindelwald und das spektakuläre Lauterbrunnental bietet Wandern und Wintersport in Postkartenkulisse. Glasklare Seen wie der Vierwaldstättersee bei Luzern mit seiner Kapellbrücke oder der Genfersee mit Montreux und den Lavaux-Weinterrassen laden zum Verweilen ein. Im sonnigen Tessin sorgen Lugano und der Lago Maggiore für mediterranes Flair. Ein Erlebnis für sich sind die legendären Panoramazüge wie der Glacier Express und der Bernina Express. Dazu kommen charmante Städte wie Bern, Zürich und Luzern. Die Schweiz ist zwar ein hochpreisiges Reiseland, belohnt aber mit überwältigender Natur, perfekter Organisation und dem wohl besten öffentlichen Verkehrsnetz der Welt.$t$, $t$Die Schweiz ist ein Alpenland der Superlative mit dem Matterhorn, dem Jungfraujoch, glasklaren Seen, charmanten Städten wie Luzern und Bern und weltberühmten Panoramazügen. Sie eignet sich ideal für Natur-, Wander-, Wintersport- und Bahnreisen und ist von Deutschland aus schnell erreichbar, jedoch vergleichsweise teuer.$t$, $t$Juni bis September für Wandern, Seen und Bergpanorama; Dezember bis März für Wintersport. Die Städte sind ganzjährig attraktiv.$t$, $t$rund eine Woche$t$, ARRAY[$t$Naturreise$t$,$t$Wandern$t$,$t$Wintersport$t$,$t$Bahnreise$t$,$t$Wellness$t$,$t$Familien$t$,$t$Roadtrip$t$]::text[], $j${"currency":"Schweizer Franken (CHF); Euro wird teils akzeptiert, meist zu ungünstigem Kurs","language":"Deutsch, Französisch, Italienisch und Rätoromanisch","flightTime":"ca. 1 bis 1,5 Stunden ab Deutschland (Zürich); sehr gut mit Bahn oder Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich; die Schweiz gehört zum Schengen-Raum (jedoch nicht zur EU)","bestMonths":"Juni bis September sowie Dezember bis März"}$j$::jsonb, $j$["Matterhorn und Zermatt – das wohl berühmteste Bergmotiv der Welt","Jungfraujoch – das „Top of Europe“ mit Gletscher und Aussichtsplattform","Berner Oberland – Interlaken, Grindelwald und das Lauterbrunnental","Luzern – Kapellbrücke und der malerische Vierwaldstättersee","Genfersee – Montreux, Schloss Chillon und die Lavaux-Weinterrassen","Panoramazüge – Glacier Express und Bernina Express durch die Alpen","Rheinfall – der größte Wasserfall Europas bei Schaffhausen","Tessin – Lugano und der Lago Maggiore mit südlichem Flair"]$j$::jsonb, $j$["Mit dem Swiss Travel Pass nutzt man Züge, Busse, Schiffe und viele Bergbahnen sowie Museen flexibel – ideal, da die Bahn in der Schweiz selbst ein Erlebnis ist.","Die Panoramazüge wie der Glacier Express und der Bernina Express zählen zu den schönsten Bahnstrecken der Welt und lohnen sich auch ohne Reservierung in regulären Zügen.","Da die Schweiz teuer ist, sparen Selbstverpfleger mit Einkäufen bei Coop oder Migros und einem Picknick mit Bergblick.","Für Aussichtsberge wie das Jungfraujoch lohnt es sich, einen klaren Tag abzuwarten und vorab die Webcams zu checken."]$j$::jsonb, $j$[{"question":"Welche Währung gilt in der Schweiz?","answer":"Bezahlt wird mit dem Schweizer Franken (CHF). Vielerorts wird zwar auch Euro akzeptiert, das Wechselgeld erfolgt jedoch in Franken und der Kurs ist meist ungünstig. Kartenzahlung ist nahezu überall möglich."},{"question":"Wann ist die beste Reisezeit für die Schweiz?","answer":"Für Wandern, Seen und Bergpanorama eignen sich Juni bis September. Wintersportler reisen zwischen Dezember und März. Die Städte sind das ganze Jahr über attraktiv."},{"question":"Brauche ich ein Visum für die Schweiz?","answer":"Nein. Die Schweiz gehört zwar nicht zur EU, ist aber Teil des Schengen-Raums. EU-Bürger benötigen kein Visum; ein gültiger Personalausweis oder Reisepass genügt."},{"question":"Braucht man in der Schweiz ein Auto?","answer":"Nein, die Schweiz hat eines der besten öffentlichen Verkehrsnetze der Welt. Mit Zügen, Bussen, Schiffen und Bergbahnen erreicht man fast jeden Ort bequem. Die Bahnfahrten selbst gehören zu den Höhepunkten einer Reise."},{"question":"Brauche ich eine Vignette für die Schweiz?","answer":"Ja, wer mit dem Auto die Schweizer Autobahnen nutzt, benötigt eine Vignette, die als Klebe- oder digitale Variante erhältlich ist und für ein Jahr gilt."},{"question":"Ist die Schweiz ein teures Reiseland?","answer":"Ja, die Schweiz zählt zu den teuersten Reiseländern der Welt, besonders bei Restaurants, Unterkünften und Bergbahnen. Mit Selbstverpflegung, Pässen für den Nahverkehr und Vorausbuchungen lässt sich jedoch sparen."},{"question":"Lohnt sich der Swiss Travel Pass?","answer":"Für Reisende, die viel mit Bahn, Bus und Schiff unterwegs sind, lohnt sich der Swiss Travel Pass oft. Er bietet freie Fahrt im öffentlichen Verkehr, Ermäßigungen auf Bergbahnen und freien Eintritt in viele Museen."},{"question":"Ist die Schweiz für einen Familienurlaub geeignet?","answer":"Ja, die Schweiz ist sehr familienfreundlich und sicher. Bergbahnen, Badeseen, einfache Wanderungen, Tiererlebnisse und kindgerechte Erlebniswelten sorgen für Abwechslung in jeder Jahreszeit."},{"question":"Welche Berge sollte man in der Schweiz sehen?","answer":"Zu den ikonischsten zählen das Matterhorn bei Zermatt, das Jungfraujoch mit Eiger, Mönch und Jungfrau im Berner Oberland sowie der Pilatus und die Rigi bei Luzern."},{"question":"Welche Spezialitäten sollte man probieren?","answer":"Typisch sind Käsefondue und Raclette, Rösti, das Zürcher Geschnetzelte sowie Schweizer Schokolade. In den Bergregionen lohnen Älplermagronen und regionale Käsesorten."},{"question":"Wie viele Tage sollte man für die Schweiz einplanen?","answer":"Für eine Region wie das Berner Oberland oder rund um Luzern reichen einige Tage. Für eine Rundreise mit mehreren Höhepunkten und Panoramazügen sollte man rund eine Woche einplanen."}]$j$::jsonb, $t$Schweiz Urlaub: Matterhorn, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Schweiz-Urlaub: das Matterhorn, das Jungfraujoch, glasklare Seen, charmante Städte und die schönsten Panoramazüge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Schweiz Reise buchen, Hotel Luzern oder Zermatt, Swiss Travel Pass, Skiurlaub Schweiz, Wanderurlaub Berner Oberland, Panoramazug Glacier Express$t$, false, $j$["oesterreich","italien","frankreich"]$j$::jsonb, ARRAY[$t$Schweiz$t$,$t$Matterhorn$t$,$t$Zermatt$t$,$t$Jungfraujoch$t$,$t$Berner Oberland$t$,$t$Interlaken$t$,$t$Grindelwald$t$,$t$Luzern$t$,$t$Vierwaldstättersee$t$,$t$Genfersee$t$,$t$Glacier Express$t$,$t$Bernina Express$t$,$t$Rheinfall$t$,$t$Bern$t$,$t$Tessin$t$,$t$Schweizer Franken$t$]::text[], $t$Die Schweiz ist ein Alpenland der Superlative, bekannt für das Matterhorn, das Jungfraujoch, glasklare Seen, charmante Städte wie Luzern und Bern sowie weltberühmte Panoramazüge wie den Glacier Express. Sie eignet sich ideal für Natur-, Wander-, Wintersport- und Bahnreisen und ist von Deutschland aus schnell erreichbar, jedoch vergleichsweise teuer. Die beste Reisezeit ist der Sommer für Wandern und der Winter für Wintersport.$t$, $t$Die Schweiz ist ein Alpenland mit dem Matterhorn, dem Jungfraujoch, glasklaren Seen und den schönsten Panoramazügen der Welt.$t$, $t$https://www.apearound.de/reiseziele/schweiz$t$, $t$/images/destinations/schweiz.jpg$t$, $t$/images/destinations/schweiz.jpg$t$, $t$Schweiz Urlaub: Matterhorn, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Schweiz-Urlaub: das Matterhorn, das Jungfraujoch, glasklare Seen, charmante Städte und die schönsten Panoramazüge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Schweiz Urlaub: Matterhorn, Alpen, Reisetipps & beste Reisezeit$t$, $t$Dein Schweiz-Urlaub: das Matterhorn, das Jungfraujoch, glasklare Seen, charmante Städte und die schönsten Panoramazüge. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Sequoia-Nationalpark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Sequoia-Nationalpark$t$, $t$sequoia$t$, $t$Vereinigte Staaten (USA)$t$, $t$Kalifornien (Sierra Nevada)$t$, $t$Nordamerika$t$, $t$/images/destinations/sequoia-hero.jpg$t$, $t$Heimat der größten Bäume der Erde in Kaliforniens Sierra Nevada – mit dem gigantischen General Sherman Tree und uralten Mammutbaumwäldern.$t$, $t$Der Sequoia-Nationalpark in der kalifornischen Sierra Nevada ist die Heimat der mächtigsten Lebewesen unseres Planeten: der Riesenmammutbäume (Giant Sequoias). Im Giant Forest steht mit dem General Sherman Tree der nach Volumen größte Baum der Erde – ein lebendiger Gigant von über 80 Metern Höhe und einem Alter von rund zweitausend Jahren. Wege wie der Congress Trail führen mitten durch diese ehrfurchtgebietenden Wälder. Vom Granitfelsen Moro Rock, den eine steile Treppe erschließt, eröffnet sich ein weiter Blick über die Sierra Nevada. Weitere Höhepunkte sind der durchfahrbare Tunnel Log und die geführten Touren durch die Tropfsteinhöhle Crystal Cave. Im Hintergrund ragt der Mount Whitney auf, der höchste Berg der kontiguösen USA. Der Park wird gemeinsam mit dem benachbarten Kings-Canyon-Nationalpark verwaltet, sodass sich beide ideal verbinden lassen. Wegen der Höhenlage ist der Sommer angenehm, im Winter liegt oft Schnee. Sequoia ist ein eindrucksvolles Ziel für Natur-, Wander- und Fotoreisen und ein lohnender Stopp in Kalifornien.$t$, $t$Der Sequoia-Nationalpark in Kaliforniens Sierra Nevada ist die Heimat der Riesenmammutbäume, darunter der General Sherman Tree, der größte Baum der Erde nach Volumen. Mit Mammutbaumwäldern, dem Aussichtsfelsen Moro Rock und der Nähe zum Kings-Canyon-Nationalpark eignet er sich ideal für Natur- und Wanderreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Mai bis Oktober mit mildem Wetter sind ideal; dank der Höhenlage bleibt es im Sommer angenehm. Im Winter liegt oft Schnee – dann sind Schneeketten häufig Pflicht und manche Straßen gesperrt.$t$, $t$1 bis 2 Tage, oft mit dem Kings-Canyon-Nationalpark kombiniert$t$, ARRAY[$t$Naturreise$t$,$t$Nationalparks$t$,$t$Roadtrip$t$,$t$Wandern$t$,$t$Fotoreise$t$,$t$Familien$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch","flightTime":"Kein Direktflug zum Park; ab Deutschland ca. 11 bis 12 Stunden in die USA plus Anschluss/Fahrt. Nächste Flughäfen: Fresno (FAT, rund 1,5 Stunden Fahrt) und Los Angeles (LAX, rund 3,5 bis 4 Stunden)","timezone":"Pacific Time (UTC−8; im Sommer UTC−7), rund neun Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"Mai bis Oktober"}$j$::jsonb, $j$["General Sherman Tree – der nach Volumen größte Baum der Erde","Giant Forest – beeindruckender Wald aus Riesenmammutbäumen","Congress Trail – Wanderweg mitten zwischen den Mammutbäumen","Moro Rock – Granitfelsen mit Treppe und weitem Panoramablick","Tunnel Log – umgestürzter Mammutbaum, durch den man hindurchfahren kann","Crystal Cave – geführte Touren durch eine Tropfsteinhöhle","Mount Whitney – höchster Berg der kontiguösen USA in der Parkregion","Kings-Canyon-Nationalpark – benachbarter Park, ideal zum Kombinieren"]$j$::jsonb, $j$["Der General Sherman Tree und der anschließende Congress Trail sind ein Muss, um die schiere Größe der Mammutbäume zu erfassen – am ruhigsten ist es früh am Morgen.","Der Aufstieg auf den Moro Rock über eine steile Treppe wird mit einem grandiosen Panorama über die Sierra Nevada belohnt.","Im Winter sind Schneeketten oft vorgeschrieben und einige Straßen gesperrt; im Sommer verkehrt im Giant Forest teils ein kostenloser Shuttle.","Lebensmittel gehören wegen der Bären in die bereitgestellten Bear Boxes; die kurvige Bergstraße zum Park erfordert zudem etwas mehr Fahrzeit als gedacht."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für den Sequoia-Nationalpark?","answer":"Am angenehmsten sind die Monate Mai bis Oktober. Dank der Höhenlage bleibt es im Sommer mild. Im Winter ist der Park geöffnet und verschneit besonders stimmungsvoll, allerdings sind dann oft Schneeketten nötig und einige Straßen gesperrt."},{"question":"Was ist der General Sherman Tree?","answer":"Der General Sherman Tree ist ein Riesenmammutbaum im Giant Forest und gilt nach Holzvolumen als größter Baum der Erde. Er ist über 80 Meter hoch und rund zweitausend Jahre alt – ein beeindruckendes Naturdenkmal."},{"question":"Wie reist man zum Sequoia-Nationalpark an?","answer":"Es gibt keinen Flughafen direkt am Park. Am nächsten liegt Fresno (rund 1,5 Stunden Fahrt), auch Los Angeles ist eine gängige Anreiseoption (rund 3,5 bis 4 Stunden). Von dort fährt man mit dem Mietwagen weiter."},{"question":"Braucht man im Sequoia-Nationalpark einen Mietwagen?","answer":"Ja, für die Anreise ist ein Mietwagen sehr empfehlenswert, da der Park abgelegen in den Bergen liegt. Im Giant Forest gibt es im Sommer teils einen kostenlosen Shuttle, der die wichtigsten Sehenswürdigkeiten verbindet."},{"question":"Brauche ich für den Sequoia ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Gilt das Eintrittsticket auch für den Kings-Canyon-Nationalpark?","answer":"Ja, beide Parks werden gemeinsam verwaltet, und ein Eintrittsticket gilt für Sequoia und Kings Canyon. Wer mehrere US-Nationalparks besucht, fährt mit dem Jahrespass „America the Beautiful“ oft günstiger."},{"question":"Sollte man Sequoia mit Kings Canyon kombinieren?","answer":"Ja, das bietet sich an. Die beiden benachbarten Parks ergänzen sich gut: Sequoia mit seinen Mammutbäumen und Kings Canyon mit seiner tiefen Schlucht und alpinen Landschaft. Im Kings Canyon steht zudem der General Grant Tree."},{"question":"Muss man im Sequoia mit Bären rechnen?","answer":"Ja, im Park leben Schwarzbären. Lebensmittel und duftende Gegenstände müssen in den bereitgestellten Bear Boxes verstaut werden und dürfen nicht im Auto bleiben. Bei Begegnungen hält man Abstand und füttert die Tiere niemals."},{"question":"Ist der Sequoia-Nationalpark für Familien geeignet?","answer":"Ja, der Park ist familienfreundlich. Die leichten Wege durch den Giant Forest, der General Sherman Tree und der durchfahrbare Tunnel Log begeistern Kinder. Auf dem steilen Moro Rock und an Abgründen ist Vorsicht geboten."},{"question":"Wie viele Tage sollte man für den Sequoia einplanen?","answer":"Für die wichtigsten Highlights wie den Giant Forest und Moro Rock reicht 1 Tag. In Kombination mit dem Kings-Canyon-Nationalpark lohnen sich 2 Tage, um beide Parks in Ruhe zu erleben."}]$j$::jsonb, $t$Sequoia-Nationalpark: Mammutbäume, General Sherman & beste Reisezeit$t$, $t$Dein Besuch im Sequoia-Nationalpark in Kalifornien: die größten Bäume der Erde, der General Sherman Tree, der Giant Forest und Moro Rock. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Sequoia Nationalpark Reise buchen, Flug nach Fresno oder Los Angeles, Mietwagen Kalifornien, Hotel nahe Sequoia, Sequoia und Kings Canyon Touren, Rundreise Kalifornien Nationalparks$t$, true, $j$["yosemite","kings-canyon","grand-canyon"]$j$::jsonb, ARRAY[$t$Sequoia-Nationalpark$t$,$t$Kalifornien$t$,$t$Sierra Nevada$t$,$t$Riesenmammutbäume$t$,$t$General Sherman Tree$t$,$t$Giant Forest$t$,$t$Congress Trail$t$,$t$Moro Rock$t$,$t$Tunnel Log$t$,$t$Crystal Cave$t$,$t$Mount Whitney$t$,$t$Kings-Canyon-Nationalpark$t$,$t$General Grant Tree$t$,$t$Fresno$t$]::text[], $t$Der Sequoia-Nationalpark in Kaliforniens Sierra Nevada ist die Heimat der Riesenmammutbäume, darunter der General Sherman Tree im Giant Forest, der nach Volumen größte Baum der Erde. Zu den Höhepunkten zählen Wanderungen durch die Mammutbaumwälder, der Aussichtsfelsen Moro Rock und der durchfahrbare Tunnel Log; der Park wird gemeinsam mit dem benachbarten Kings-Canyon-Nationalpark verwaltet. Er eignet sich ideal für Natur- und Wanderreisen, am besten von Mai bis Oktober; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Der Sequoia-Nationalpark in Kalifornien ist die Heimat der größten Bäume der Erde, darunter der General Sherman Tree, am besten von Mai bis Oktober zu besuchen.$t$, $t$https://www.apearound.de/reiseziele/sequoia$t$, $t$/images/destinations/sequoia.jpg$t$, $t$/images/destinations/sequoia.jpg$t$, $t$Sequoia-Nationalpark: Mammutbäume, General Sherman & beste Reisezeit$t$, $t$Dein Besuch im Sequoia-Nationalpark in Kalifornien: die größten Bäume der Erde, der General Sherman Tree, der Giant Forest und Moro Rock. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Sequoia-Nationalpark: Mammutbäume, General Sherman & beste Reisezeit$t$, $t$Dein Besuch im Sequoia-Nationalpark in Kalifornien: die größten Bäume der Erde, der General Sherman Tree, der Giant Forest und Moro Rock. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$draft$t$)
