-- Singapur
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Singapur$t$, $t$singapur$t$, $t$Singapur$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/singapur-hero.jpg$t$, $t$Faszinierender Stadtstaat, der futuristische Skyline, üppige Gärten, multikulturelle Viertel und weltberühmtes Hawker-Streetfood auf engstem Raum vereint.$t$, $t$Singapur ist einer der faszinierendsten Stadtstaaten der Welt – sauber, sicher, hochmodern und zugleich überraschend grün. Das Wahrzeichen ist das Marina Bay Sands mit seiner spektakulären Skyline, davor reckt sich der Merlion über die Bucht. In den Gardens by the Bay ragen die futuristischen Supertrees in den Himmel, während die klimatisierten Gewächshäuser Cloud Forest und Flower Dome ganze Landschaften nachbilden. Singapurs Stärke ist seine Vielfalt: In Chinatown, Little India und dem von der malaiischen Kultur geprägten Kampong Glam treffen Religionen, Architektur und vor allem Aromen aufeinander. Die Hawker Centres gelten als kulinarisches Herz der Stadt, in dem Gerichte wie Hainanese Chicken Rice, Laksa und Chili Crab günstig und in Weltklasse-Qualität serviert werden. Familien lieben die Erlebniswelten auf der Insel Sentosa und den preisgekrönten Zoo. Singapur ist von Deutschland aus direkt erreichbar und eignet sich perfekt für eine kompakte Städtereise oder als komfortabler Stopover.$t$, $t$Singapur ist ein hochmoderner, grüner Stadtstaat in Südostasien mit dem Marina Bay Sands, den Gardens by the Bay, multikulturellen Vierteln wie Chinatown und Little India sowie weltberühmtem Hawker-Streetfood. Er ist sauber, sicher und bestens erschlossen und eignet sich ideal für eine kompakte Städtereise oder als Stopover.$t$, $t$Singapur ist als äquatornahes Reiseziel ganzjährig warm und feucht und damit das ganze Jahr über bereisbar; etwas trockener sind oft die Monate Februar bis April.$t$, $t$2 bis 4 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Kulinarik$t$,$t$Familien$t$,$t$Shopping$t$,$t$Stopover$t$,$t$Kulturreise$t$]::text[], $j${"currency":"Singapur-Dollar (SGD)","language":"Englisch (Amtssprache neben Malaiisch, Mandarin und Tamil)","flightTime":"ca. 12 bis 13 Stunden ab Deutschland im Direktflug","timezone":"SGT (UTC+8), sieben Stunden vor MEZ","visa":"Visumfreier Aufenthalt bis 90 Tage; vor der Einreise ist die digitale SG Arrival Card online auszufüllen","bestMonths":"Ganzjährig; etwas trockener Februar bis April"}$j$::jsonb, $j$["Marina Bay Sands – ikonische Skyline und Aussicht über die Bucht","Gardens by the Bay – futuristische Supertrees und die Gewächshäuser Cloud Forest und Flower Dome","Hawker Centres – weltberühmtes, günstiges Streetfood, teils mit Michelin-Auszeichnung","Chinatown, Little India und Kampong Glam – multikulturelle Viertel voller Aromen","Sentosa – Universal Studios, Strände und Freizeitwelten","Singapore Zoo und Night Safari – einer der besten Zoos der Welt","Merlion und Marina Bay – das Wahrzeichen am Wasser","Botanic Gardens – UNESCO-Welterbe mit berühmtem Orchideengarten"]$j$::jsonb, $j$["Am besten isst man in den Hawker Centres wie Maxwell oder Lau Pa Sat – Klassiker wie Hainanese Chicken Rice, Laksa und Chili Crab gibt es dort günstig und hervorragend.","Die abendliche Lichtshow „Garden Rhapsody“ bei den Supertrees in den Gardens by the Bay ist kostenlos und ein echtes Highlight.","Innerhalb der Stadt kommt man mit der MRT schnell, günstig und klimatisiert überallhin – ein Auto ist völlig überflüssig.","Singapur ist für strenge Regeln bekannt: Bußgelder drohen etwa für das Wegwerfen von Müll oder Essen und Trinken in der MRT, daher lohnt sich ein Blick auf die Vorschriften."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Singapur?","answer":"Deutsche Staatsbürger können für touristische Aufenthalte bis zu 90 Tage visumfrei einreisen. Vor der Einreise ist jedoch die digitale SG Arrival Card online auszufüllen. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Singapur?","answer":"Singapur liegt nahe am Äquator und ist ganzjährig warm und feucht, somit jederzeit bereisbar. Etwas trockener sind häufig die Monate Februar bis April; kurze, heftige Schauer können aber das ganze Jahr über auftreten."},{"question":"Welche Währung gilt in Singapur?","answer":"Gezahlt wird mit dem Singapur-Dollar (SGD). Kartenzahlung und kontaktloses Bezahlen sind nahezu überall möglich; etwas Bargeld ist nur an manchen Hawker-Ständen praktisch."},{"question":"Wie bewegt man sich am besten in Singapur fort?","answer":"Das beste Verkehrsmittel ist die MRT, ein schnelles, günstiges und klimatisiertes U-Bahn-Netz. Dazu gibt es Busse und Fahrdienste wie Grab. Ein Mietwagen ist wegen hoher Kosten und Gebühren nicht zu empfehlen und auch unnötig."},{"question":"Ist Singapur ein teures Reiseziel?","answer":"Singapur gehört zu den teureren Zielen Asiens, besonders bei Hotels und Alkohol. Beim Essen lässt sich jedoch hervorragend sparen, da die Hawker Centres erstklassige Gerichte zu günstigen Preisen bieten."},{"question":"Kann man in Singapur das Leitungswasser trinken?","answer":"Ja, anders als in vielen Nachbarländern hat Singapur Trinkwasserqualität direkt aus der Leitung. Das Leitungswasser ist sicher und kann bedenkenlos getrunken werden."},{"question":"Ist Singapur für einen Familienurlaub geeignet?","answer":"Ja, Singapur ist äußerst familienfreundlich und sicher. Die Insel Sentosa mit Universal Studios, der Zoo mit Night Safari, die Gardens by the Bay und zahlreiche kindgerechte Attraktionen sorgen für viel Abwechslung."},{"question":"Lohnt sich Singapur als Stopover?","answer":"Auf jeden Fall. Dank des Direktflugs und der kompakten Größe lässt sich Singapur ideal als Zwischenstopp auf dem Weg nach Australien oder Südostasien einbauen; schon 2 bis 3 Tage reichen für die Höhepunkte."},{"question":"Ist Singapur sicher?","answer":"Ja, Singapur zählt zu den sichersten Städten der Welt mit sehr niedriger Kriminalität. Die strengen Gesetze sollte man jedoch ernst nehmen, da bereits kleinere Verstöße empfindliche Bußgelder nach sich ziehen können."},{"question":"Welche Gerichte sollte man in Singapur probieren?","answer":"Unbedingt probieren sollte man Hainanese Chicken Rice, Laksa, Chili Crab, Char Kway Teow, Satay sowie Kaya Toast zum Frühstück. Die multikulturelle Küche aus chinesischen, malaiischen und indischen Einflüssen ist ein Highlight."},{"question":"Wie viele Tage sollte man für Singapur einplanen?","answer":"Für die wichtigsten Highlights reichen 2 bis 4 Tage. Wer auch Sentosa, den Zoo und mehrere Viertel in Ruhe erleben möchte, kann problemlos länger bleiben."}]$j$::jsonb, $t$Singapur Städtereise: Marina Bay, Tipps & beste Reisezeit$t$, $t$Deine Singapur-Reise: Marina Bay Sands, Gardens by the Bay, Hawker-Streetfood, Sentosa und multikulturelle Viertel. Beste Reisezeit, Einreise, Highlights und Reisetipps im Überblick.$t$, $t$Singapur Städtereise buchen, Flug nach Singapur, Hotel Marina Bay, Stopover Singapur, Sentosa Tickets, Singapur mit Kindern$t$, false, $j$["malaysia","thailand","hongkong"]$j$::jsonb, ARRAY[$t$Singapur$t$,$t$Marina Bay Sands$t$,$t$Gardens by the Bay$t$,$t$Supertrees$t$,$t$Merlion$t$,$t$Sentosa$t$,$t$Hawker Centre$t$,$t$Chinatown$t$,$t$Little India$t$,$t$Kampong Glam$t$,$t$Singapore Zoo$t$,$t$Botanic Gardens$t$,$t$Orchard Road$t$,$t$MRT$t$,$t$Singapur-Dollar$t$,$t$Chili Crab$t$]::text[], $t$Singapur ist ein hochmoderner, grüner Stadtstaat in Südostasien, bekannt für das Marina Bay Sands, die futuristischen Gardens by the Bay, multikulturelle Viertel wie Chinatown und Little India sowie weltberühmtes Hawker-Streetfood. Die Stadt ist sauber, sicher und mit der MRT bestens erschlossen und eignet sich ideal für eine kompakte Städtereise oder als komfortabler Stopover. Singapur ist ganzjährig bereisbar und von Deutschland aus direkt erreichbar.$t$, $t$Singapur ist ein moderner, grüner Stadtstaat mit Marina Bay Sands, Gardens by the Bay und weltberühmtem Hawker-Streetfood, ideal für Städtereise oder Stopover.$t$, $t$https://www.apearound.de/reiseziele/singapur$t$, $t$/images/destinations/singapur.jpg$t$, $t$/images/destinations/singapur.jpg$t$, $t$Singapur Städtereise: Marina Bay, Tipps & beste Reisezeit$t$, $t$Deine Singapur-Reise: Marina Bay Sands, Gardens by the Bay, Hawker-Streetfood, Sentosa und multikulturelle Viertel. Beste Reisezeit, Einreise, Highlights und Reisetipps im Überblick.$t$, $t$Singapur Städtereise: Marina Bay, Tipps & beste Reisezeit$t$, $t$Deine Singapur-Reise: Marina Bay Sands, Gardens by the Bay, Hawker-Streetfood, Sentosa und multikulturelle Viertel. Beste Reisezeit, Einreise, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Slowenien
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Slowenien$t$, $t$slowenien$t$, $t$Slowenien$t$, $t$Mitteleuropa$t$, $t$Europa$t$, $t$/images/destinations/slowenien-hero.jpg$t$, $t$Grünes Naturparadies zwischen Alpen und Adria mit dem märchenhaften Bleder See, türkisem Soča-Fluss, Tropfsteinhöhlen und charmanter Hauptstadt Ljubljana.$t$, $t$Slowenien ist eines der grünsten und vielseitigsten Länder Europas und vereint auf kleinem Raum Alpen, Karstlandschaften und Adriaküste. Das Wahrzeichen ist der märchenhafte Bleder See mit seiner Kircheninsel und der thronenden Burg. In den Julischen Alpen lockt der Triglav-Nationalpark mit Gipfeln, Wäldern und dem ruhigen Bohinjer See, während das türkisblaue Soča-Tal zu den schönsten Flusslandschaften des Kontinents zählt und Rafting- und Wanderfans begeistert. Unter der Erde beeindrucken die riesige Postojna-Höhle und die UNESCO-geschützten Škocjan-Höhlen. Die charmante Hauptstadt Ljubljana mit ihrer autofreien Altstadt, der Drachenbrücke und lebendiger Café-Kultur gilt als eine der grünsten Städte Europas. Im Südwesten reicht das Land bis ans Mittelmeer, wo das venezianisch geprägte Küstenstädtchen Piran wartet. Slowenien ist von Deutschland aus gut erreichbar und ideal für Natur-, Aktiv- und Rundreisen.$t$, $t$Slowenien ist ein grünes Naturparadies zwischen Alpen und Adria mit dem Bleder See, dem Triglav-Nationalpark, dem türkisen Soča-Tal, beeindruckenden Tropfsteinhöhlen und der charmanten Hauptstadt Ljubljana. Es eignet sich ideal für Natur-, Aktiv- und Rundreisen und ist von Deutschland aus gut erreichbar.$t$, $t$Mai bis September für Seen, Berge und Aktivurlaub; das Soča-Tal ist im Sommer ideal zum Rafting, im Winter laden die Alpen zum Skifahren ein.$t$, $t$5 bis 7 Tage$t$, ARRAY[$t$Naturreise$t$,$t$Aktivurlaub$t$,$t$Wandern$t$,$t$Städtereise$t$,$t$Roadtrip$t$,$t$Familien$t$]::text[], $j${"currency":"Euro (EUR)","language":"Slowenisch","flightTime":"ca. 1 bis 1,5 Stunden ab Deutschland (Ljubljana); aus Süddeutschland auch gut mit dem Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Bleder See – Kircheninsel, Burg und das berühmteste Postkartenmotiv des Landes","Ljubljana – autofreie Altstadt, Drachenbrücke und lebendige Café-Kultur","Triglav-Nationalpark – Julische Alpen mit Gipfeln, Wäldern und Wanderwegen","Soča-Tal – türkisblauer Fluss, ideal zum Rafting und Wandern","Postojna-Höhle und Predjama-Burg – riesiges Tropfsteinsystem und Felsenburg","Bohinjer See – ruhigere, natürliche Alternative zum Bleder See","Škocjan-Höhlen – UNESCO-Welterbe mit gewaltigem unterirdischem Canyon","Piran – venezianisch geprägtes Küstenstädtchen an der Adria"]$j$::jsonb, $j$["Auf der Insel im Bleder See gehört eine Fahrt mit dem traditionellen Pletna-Boot ebenso dazu wie ein Stück der berühmten Cremeschnitte (Kremna rezina) am Ufer.","Wer es ruhiger mag, weicht vom oft vollen Bleder See auf den nahegelegenen, naturbelasseneren Bohinjer See aus.","Die malerische Vintgar-Klamm bei Bled lässt sich am entspanntesten früh am Morgen erkunden, bevor die Tagesausflügler eintreffen.","Im Sommer lohnt sich im Soča-Tal eine Rafting- oder Kajaktour auf dem leuchtend türkisfarbenen Fluss – ein echtes Naturerlebnis."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Slowenien?","answer":"Für Seen, Berge und Aktivurlaub eignen sich die Monate Mai bis September. Das Soča-Tal ist im Sommer ideal zum Rafting, während die Alpen im Winter Möglichkeiten zum Skifahren bieten."},{"question":"Welche Währung gilt in Slowenien?","answer":"In Slowenien zahlt man mit dem Euro (EUR); das Land gehört seit 2007 zur Eurozone. Kartenzahlung ist weit verbreitet, etwas Bargeld empfiehlt sich für kleinere Orte und Märkte."},{"question":"Brauche ich ein Visum für Slowenien?","answer":"Nein. Slowenien ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Lohnt sich ein Mietwagen in Slowenien?","answer":"Ja, für die Erkundung der Seen, des Triglav-Nationalparks, des Soča-Tals und der Küste ist ein Auto sehr praktisch. Ljubljana selbst lässt sich dagegen gut zu Fuß und mit dem Rad erkunden."},{"question":"Kann man mit dem eigenen Auto nach Slowenien fahren?","answer":"Ja, besonders aus Süddeutschland ist Slowenien gut mit dem Auto erreichbar. Für die Autobahnen benötigt man eine elektronische Vignette (E-Vignette), die man vorab oder im Land erwerben kann."},{"question":"Was kann man am Bleder See unternehmen?","answer":"Beliebt sind eine Bootsfahrt zur Kircheninsel, der Aufstieg zur Burg von Bled mit Seeblick, ein Spaziergang um den See sowie Ausflüge zur nahen Vintgar-Klamm. Im Sommer lädt der See auch zum Baden ein."},{"question":"Welche Höhlen sollte man in Slowenien besuchen?","answer":"Besonders sehenswert sind die Postojna-Höhle mit ihrer Höhlenbahn und die nahe Felsenburg Predjama sowie die UNESCO-geschützten Škocjan-Höhlen mit ihrem gewaltigen unterirdischen Canyon."},{"question":"Hat Slowenien auch Meer und Strände?","answer":"Ja, Slowenien besitzt einen kurzen, aber reizvollen Küstenabschnitt an der Adria. Orte wie das venezianisch geprägte Piran und das Seebad Portorož laden zum Bummeln und Baden ein."},{"question":"Ist Slowenien für einen Familienurlaub geeignet?","answer":"Ja, Slowenien ist familienfreundlich und sicher. Badeseen, einfache Wanderungen, Höhlen, Tierparks und eine kompakte Größe mit kurzen Wegen machen es zu einem idealen Ziel für Familien."},{"question":"Spricht man in Slowenien Deutsch oder Englisch?","answer":"Viele Slowenen sprechen gut Englisch und oft auch Deutsch, besonders in touristischen Regionen. Die Verständigung ist für deutsche Reisende daher meist unkompliziert."},{"question":"Wie viele Tage sollte man für Slowenien einplanen?","answer":"Für die wichtigsten Höhepunkte wie Ljubljana, Bled und eine Naturregion reichen 5 bis 7 Tage. Wer zusätzlich das Soča-Tal, die Höhlen und die Küste verbinden möchte, plant besser etwas mehr Zeit ein."}]$j$::jsonb, $t$Slowenien Urlaub: Bleder See, Natur, Reisetipps & beste Reisezeit$t$, $t$Dein Slowenien-Urlaub: der märchenhafte Bleder See, der Triglav-Nationalpark, das türkise Soča-Tal, Tropfsteinhöhlen und Ljubljana. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Slowenien Reise buchen, Hotel Bled oder Ljubljana, Mietwagen Slowenien vergleichen, Aktivurlaub Soča-Tal, Rundreise Slowenien, Wanderurlaub Julische Alpen$t$, true, $j$["kroatien","oesterreich","italien"]$j$::jsonb, ARRAY[$t$Slowenien$t$,$t$Bleder See$t$,$t$Ljubljana$t$,$t$Triglav-Nationalpark$t$,$t$Soča-Tal$t$,$t$Postojna-Höhle$t$,$t$Predjama$t$,$t$Škocjan-Höhlen$t$,$t$Bohinjer See$t$,$t$Piran$t$,$t$Vintgar-Klamm$t$,$t$Julische Alpen$t$,$t$Drachenbrücke$t$,$t$Adria$t$,$t$Portorož$t$]::text[], $t$Slowenien ist ein grünes Naturparadies zwischen Alpen und Adria, bekannt für den märchenhaften Bleder See, den Triglav-Nationalpark, das türkisblaue Soča-Tal, beeindruckende Tropfsteinhöhlen und die charmante Hauptstadt Ljubljana. Das vielseitige Land eignet sich ideal für Natur-, Aktiv- und Rundreisen und ist von Deutschland aus gut erreichbar. Die beste Reisezeit liegt zwischen Mai und September.$t$, $t$Slowenien ist ein grünes Naturland zwischen Alpen und Adria mit dem Bleder See, dem Soča-Tal, Tropfsteinhöhlen und der Hauptstadt Ljubljana.$t$, $t$https://www.apearound.de/reiseziele/slowenien$t$, $t$/images/destinations/slowenien.jpg$t$, $t$/images/destinations/slowenien.jpg$t$, $t$Slowenien Urlaub: Bleder See, Natur, Reisetipps & beste Reisezeit$t$, $t$Dein Slowenien-Urlaub: der märchenhafte Bleder See, der Triglav-Nationalpark, das türkise Soča-Tal, Tropfsteinhöhlen und Ljubljana. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Slowenien Urlaub: Bleder See, Natur, Reisetipps & beste Reisezeit$t$, $t$Dein Slowenien-Urlaub: der märchenhafte Bleder See, der Triglav-Nationalpark, das türkise Soča-Tal, Tropfsteinhöhlen und Ljubljana. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Spanien
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Spanien$t$, $t$spanien$t$, $t$Spanien$t$, $t$Südwesteuropa$t$, $t$Europa$t$, $t$/images/destinations/spanien-hero.jpg$t$, $t$Sonniges Sehnsuchtsland mit Barcelona und Madrid, der maurischen Pracht Andalusiens, den Balearen, endlosen Stränden, Tapas und Lebensfreude.$t$, $t$Spanien zählt zu den beliebtesten Reiseländern der Deutschen und vereint pulsierende Metropolen, reiche Geschichte, traumhafte Küsten und eine ausgeprägte Lebensfreude. Barcelona begeistert mit der unvollendeten Sagrada Família und den fantasievollen Bauten Antoni Gaudís, Madrid mit Weltklasse-Museen wie dem Prado und dem königlichen Flair. In Andalusien treffen maurisches Erbe und Flamenco aufeinander – allen voran die Alhambra in Granada, die Mezquita in Córdoba und das stolze Sevilla. Sonnenanbeter zieht es an die Costa Brava, die Costa del Sol oder auf die Baleareninseln Mallorca, Ibiza und Menorca, während die Kanarischen Inseln ganzjährig wärmen. Valencia lockt mit moderner Architektur und der Heimat der Paella, das Baskenland mit San Sebastián und seinen Pintxos. Dazu kommt die spanische Esskultur mit Tapas, gutem Wein und spätem Abendessen. Ob Strandurlaub, Städtetrip, Rundreise oder Genussreise – Spanien bietet Vielfalt für jeden Geschmack und ist bequem erreichbar.$t$, $t$Spanien ist ein vielseitiges, sonniges Reiseland mit Metropolen wie Barcelona und Madrid, der maurischen Pracht Andalusiens, den Baleareninseln, den ganzjährig warmen Kanaren und endlosen Stränden. Berühmt für Tapas, Kultur und Lebensfreude, eignet es sich ideal für Strandurlaub, Städtereisen, Rundreisen und Genussreisen und ist von Deutschland aus gut erreichbar.$t$, $t$April bis Juni sowie September und Oktober für Städte und mildes Wetter; der Sommer eignet sich für Strandurlaub, die Kanaren sind ganzjährig warm.$t$, $t$Städtereise 3 bis 4 Tage, Rundreise 1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Städtereise$t$,$t$Kulturreise$t$,$t$Kulinarik$t$,$t$Rundreise$t$,$t$Familien$t$,$t$Inselurlaub$t$]::text[], $j${"currency":"Euro (EUR)","language":"Spanisch (Kastilisch); regional auch Katalanisch, Galicisch und Baskisch","flightTime":"ca. 2 bis 3 Stunden ab Deutschland (Madrid, Barcelona, Mallorca)","timezone":"MEZ (UTC+1) auf dem Festland; die Kanaren liegen eine Stunde zurück (UTC+0)","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"April bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Barcelona – Sagrada Família, Gaudí-Bauten, Park Güell und Las Ramblas","Madrid – der Prado, der Königspalast und der Retiro-Park","Andalusien – Alhambra in Granada, Mezquita in Córdoba und Sevilla","Mallorca und die Balearen – Strände, Buchten und mediterranes Inselleben","Kanarische Inseln – ganzjährig warmes Klima auf Teneriffa, Gran Canaria und Co.","Valencia – Stadt der Künste und Wissenschaften und Heimat der Paella","San Sebastián und das Baskenland – Pintxos und Spitzengastronomie","Santiago de Compostela – Pilgerziel des Jakobswegs"]$j$::jsonb, $j$["Tapas oder baskische Pintxos genießt man am besten auf einer kleinen Tour von Bar zu Bar – so probiert man sich durch viele Spezialitäten.","In Spanien wird spät gegessen: Restaurants füllen sich oft erst ab 21 oder 22 Uhr, und mittags sind viele Geschäfte zur Siesta geschlossen.","Tickets für die Alhambra in Granada und die Sagrada Família in Barcelona sollte man unbedingt frühzeitig online buchen, da sie schnell ausverkauft sind.","Für Städtereisen ins heiße Landesinnere wie Madrid oder Sevilla sind Frühling und Herbst angenehmer als der oft sehr heiße Hochsommer."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für Spanien?","answer":"Für Städte und Kultur sind April bis Juni sowie September und Oktober ideal. Der Sommer eignet sich für Strandurlaub an den Küsten und auf den Inseln, ist im Landesinneren jedoch sehr heiß. Die Kanaren sind ganzjährig warm."},{"question":"Welche Währung gilt in Spanien?","answer":"In Spanien zahlt man mit dem Euro (EUR). Kartenzahlung ist weit verbreitet, etwas Bargeld empfiehlt sich für kleine Bars, Märkte und Trinkgeld."},{"question":"Brauche ich ein Visum für Spanien?","answer":"Nein. Spanien ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Lohnt sich ein Mietwagen in Spanien?","answer":"Für Städte wie Barcelona und Madrid ist ein Auto nicht nötig, da der Nahverkehr sehr gut ist. Für Rundreisen durch Andalusien, das Baskenland oder entlang der Küsten ist ein Mietwagen jedoch sehr empfehlenswert."},{"question":"Welche Städte in Spanien sollte man besuchen?","answer":"Zu den beliebtesten zählen Barcelona, Madrid, Sevilla, Granada, Córdoba, Valencia und San Sebastián. Welche sich am meisten lohnen, hängt von den eigenen Interessen und der Reisezeit ab."},{"question":"Welche Inseln gehören zu Spanien?","answer":"Zu Spanien gehören die Balearen im Mittelmeer (Mallorca, Ibiza, Menorca, Formentera) sowie die Kanarischen Inseln im Atlantik (Teneriffa, Gran Canaria, Lanzarote, Fuerteventura und weitere)."},{"question":"Ist Spanien für einen Familienurlaub geeignet?","answer":"Ja, Spanien ist sehr familienfreundlich. Flache Strände, Ferienanlagen, Freizeitparks wie der PortAventura, kindgerechte Städte und das warme Klima machen es zu einem idealen Ziel für Familien."},{"question":"Wann essen die Spanier zu Abend?","answer":"Deutlich später als in Deutschland: Das Abendessen beginnt häufig erst zwischen 21 und 22 Uhr. Mittags gibt es vielerorts eine Siesta, in der kleinere Geschäfte schließen."},{"question":"Welche Spezialitäten sollte man in Spanien probieren?","answer":"Typisch sind Tapas, Paella aus Valencia, Jamón Ibérico, Gazpacho, Tortilla Española sowie im Baskenland Pintxos. Dazu passen spanische Weine, Sangria und Cava."},{"question":"Spricht man in Spanien Englisch?","answer":"In touristischen Orten und größeren Städten kommt man mit Englisch meist zurecht. Abseits davon sind die Kenntnisse geringer – ein paar spanische Höflichkeitsfloskeln werden geschätzt."},{"question":"Wie viele Tage sollte man für Spanien einplanen?","answer":"Für eine Stadt wie Barcelona oder Madrid reichen 3 bis 4 Tage. Für eine Rundreise durch Andalusien oder mehrere Regionen sollte man 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Spanien Urlaub: Barcelona, Andalusien, Strände & beste Reisezeit$t$, $t$Dein Spanien-Urlaub: Barcelona und Madrid, die maurische Pracht Andalusiens, die Balearen und Kanaren sowie endlose Strände. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Spanien Urlaub buchen, Flug und Hotel Barcelona oder Mallorca, Mietwagen Spanien vergleichen, Rundreise Andalusien, Strandurlaub Costa Brava, Städtereise Madrid$t$, true, $j$["portugal","italien","griechenland"]$j$::jsonb, ARRAY[$t$Spanien$t$,$t$Barcelona$t$,$t$Sagrada Família$t$,$t$Gaudí$t$,$t$Madrid$t$,$t$Prado$t$,$t$Andalusien$t$,$t$Alhambra$t$,$t$Granada$t$,$t$Sevilla$t$,$t$Córdoba$t$,$t$Mallorca$t$,$t$Balearen$t$,$t$Kanarische Inseln$t$,$t$Valencia$t$,$t$Tapas$t$]::text[], $t$Spanien ist ein vielseitiges, sonniges Reiseland mit Metropolen wie Barcelona und Madrid, der maurischen Pracht Andalusiens samt Alhambra, den Baleareninseln, den ganzjährig warmen Kanaren und endlosen Stränden. Berühmt für Tapas, Kultur und Lebensfreude, eignet es sich ideal für Strandurlaub, Städtereisen, Rundreisen und Genussreisen und ist von Deutschland aus gut erreichbar. Die beste Reisezeit für Städte liegt im Frühling und Frühherbst.$t$, $t$Spanien ist ein vielseitiges Sonnenland mit Barcelona, Madrid, dem maurischen Andalusien, den Balearen und Kanaren sowie Tapas und endlosen Stränden.$t$, $t$https://www.apearound.de/reiseziele/spanien$t$, $t$/images/destinations/spanien.jpg$t$, $t$/images/destinations/spanien.jpg$t$, $t$Spanien Urlaub: Barcelona, Andalusien, Strände & beste Reisezeit$t$, $t$Dein Spanien-Urlaub: Barcelona und Madrid, die maurische Pracht Andalusiens, die Balearen und Kanaren sowie endlose Strände. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Spanien Urlaub: Barcelona, Andalusien, Strände & beste Reisezeit$t$, $t$Dein Spanien-Urlaub: Barcelona und Madrid, die maurische Pracht Andalusiens, die Balearen und Kanaren sowie endlose Strände. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Südkorea
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Südkorea$t$, $t$suedkorea$t$, $t$Südkorea (Republik Korea)$t$, $t$Ostasien$t$, $t$Asien$t$, $t$/images/destinations/suedkorea-hero.jpg$t$, $t$Dynamisches Land zwischen Hightech und Tradition mit dem pulsierenden Seoul, alten Palästen, K-Pop, koreanischer Küche, der Insel Jeju und der DMZ.$t$, $t$Südkorea ist ein faszinierendes Reiseland, das modernste Technologie, jahrhundertealte Kultur und eine weltweit ausstrahlende Popkultur vereint. Die Hauptstadt Seoul pulsiert rund um die Uhr: prächtige Königspaläste wie Gyeongbokgung und das traditionelle Hanok-Dorf Bukchon treffen auf die Hightech-Viertel Gangnam und die Shopping- und Streetfood-Meile Myeongdong, überragt vom N Seoul Tower. Die Hafenstadt Busan begeistert mit Stränden, dem farbenfrohen Gamcheon Culture Village und dem Küstentempel Haedong Yonggungsa. Die Vulkaninsel Jeju lockt mit Natur, Stränden und dem Berg Hallasan, während die alte Königsstadt Gyeongju mit dem Bulguksa-Tempel ein Freilichtmuseum koreanischer Geschichte ist. An der Grenze zu Nordkorea lässt sich die demilitarisierte Zone (DMZ) besuchen. Dazu kommen die weltweit beliebte K-Pop- und Hallyu-Kultur sowie die exzellente koreanische Küche mit Barbecue, Kimchi und Bibimbap. Dank des hervorragenden Nahverkehrs und der KTX-Schnellzüge reist man bequem. Südkorea ist ideal für Städte-, Kultur- und Kulinarikreisen.$t$, $t$Südkorea ist ein dynamisches Reiseland in Ostasien zwischen Hightech und Tradition mit dem pulsierenden Seoul, alten Palästen, der Hafenstadt Busan, der Insel Jeju, der DMZ sowie K-Pop und exzellenter Küche. Es ist visumfrei und derzeit ohne K-ETA bereisbar und eignet sich ideal für Städte-, Kultur- und Kulinarikreisen.$t$, $t$Frühling (April bis Mai) zur Kirschblüte und Herbst (September bis November) zur Laubfärbung sind ideal; der Sommer ist heiß, schwül und regenreich, der Winter kalt, aber gut für Wintersport.$t$, $t$1 bis 2 Wochen$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Kulinarik$t$,$t$Rundreise$t$,$t$Shopping$t$,$t$Naturreise$t$]::text[], $j${"currency":"Südkoreanischer Won (KRW)","language":"Koreanisch","flightTime":"ca. 11 Stunden ab Deutschland im Direktflug (Seoul-Incheon)","timezone":"KST (UTC+9), acht Stunden vor MEZ","visa":"Kein Visum nötig (bis 90 Tage); die K-ETA ist für Deutsche bis 31.12.2026 ausgesetzt, jedoch ist die kostenlose e-Arrival Card online auszufüllen","bestMonths":"April bis Mai sowie September bis November"}$j$::jsonb, $j$["Seoul – Gyeongbokgung-Palast, Bukchon-Hanok-Dorf, Myeongdong und der N Seoul Tower","Busan – Strände, das Gamcheon Culture Village und der Küstentempel Haedong Yonggungsa","Jeju – Vulkaninsel mit dem Berg Hallasan, Stränden und Natur","DMZ – die demilitarisierte Zone an der Grenze zu Nordkorea","Gyeongju – alte Königsstadt mit dem Bulguksa-Tempel, UNESCO-Welterbe","K-Pop und Hallyu – die weltweit beliebte koreanische Popkultur","Koreanische Küche – Barbecue, Kimchi, Bibimbap und Streetfood","Seoraksan-Nationalpark – beeindruckende Berglandschaft, besonders im Herbst"]$j$::jsonb, $j$["Für den Nahverkehr lohnt sich eine aufladbare T-money-Karte; zwischen den Städten reist man schnell und komfortabel mit dem KTX-Hochgeschwindigkeitszug.","Unbedingt koreanisches Barbecue und Streetfood probieren – etwa auf dem Gwangjang-Markt in Seoul oder in den lebhaften Gassen von Myeongdong.","Die Kirschblüte erlebt man im April, die spektakuläre Laubfärbung im Oktober und November – beide Zeiten sind sehr beliebt und sollten früh gebucht werden.","Vor der Einreise muss die kostenlose e-Arrival Card online ausgefüllt werden; eine K-ETA ist für Deutsche derzeit nicht erforderlich."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum oder eine K-ETA für Südkorea?","answer":"Deutsche Staatsbürger können für Aufenthalte bis zu 90 Tagen visumfrei einreisen. Die K-ETA-Pflicht ist für Deutsche bis zum 31. Dezember 2026 ausgesetzt, sodass derzeit keine K-ETA nötig ist. Verpflichtend ist jedoch die kostenlose e-Arrival Card, die online ausgefüllt wird. Da sich die Regelung ändern kann, sollte man den aktuellen Stand prüfen."},{"question":"Was ist die e-Arrival Card?","answer":"Die e-Arrival Card ist ein kostenloses elektronisches Einreiseformular, das man innerhalb von drei Tagen vor der Einreise online ausfüllt. Sie ersetzt das frühere Papierformular und ist für visumfreie Einreisende Pflicht."},{"question":"Wann ist die beste Reisezeit für Südkorea?","answer":"Am schönsten sind das Frühjahr mit der Kirschblüte (April bis Mai) und der Herbst mit der Laubfärbung (September bis November). Der Sommer ist heiß, schwül und regenreich, der Winter kalt, aber gut für Wintersport."},{"question":"Welche Währung gilt in Südkorea?","answer":"Gezahlt wird mit dem Südkoreanischen Won (KRW). Kartenzahlung ist sehr weit verbreitet und oft Standard; etwas Bargeld ist nur an wenigen Orten wie Märkten praktisch."},{"question":"Wie reist man am besten innerhalb Südkoreas?","answer":"Das Land hat einen hervorragenden öffentlichen Nahverkehr. Zwischen den Städten fährt der KTX-Hochgeschwindigkeitszug, in Seoul und Busan gibt es ausgezeichnete Metros. Eine T-money-Karte erleichtert das Bezahlen. Ein Mietwagen ist meist nicht nötig."},{"question":"Spricht man in Südkorea Englisch?","answer":"In Seoul, an touristischen Orten und bei jüngeren Menschen kommt man mit Englisch oft zurecht, und vieles ist beschildert. Abseits davon ist Englisch begrenzt; eine Übersetzungs-App hilft weiter."},{"question":"Kann man von Südkorea aus die DMZ besuchen?","answer":"Ja, die demilitarisierte Zone (DMZ) an der Grenze zu Nordkorea lässt sich im Rahmen geführter Touren ab Seoul besuchen. Sie gibt einen eindrücklichen Einblick in die Teilung der koreanischen Halbinsel."},{"question":"Ist Südkorea für einen Familienurlaub geeignet?","answer":"Ja, Südkorea ist sehr sicher, sauber und familienfreundlich. Themen- und Wasserparks, moderne Städte, Strände auf Jeju und kindgerechtes Essen sorgen für Abwechslung. Die gute Infrastruktur macht das Reisen unkompliziert."},{"question":"Welche Gerichte sollte man in Südkorea probieren?","answer":"Unbedingt probieren sollte man koreanisches Barbecue (Galbi, Bulgogi), Bibimbap, Kimchi, Tteokbokki (scharfe Reiskuchen), Korean Fried Chicken sowie verschiedene Streetfood-Spezialitäten."},{"question":"Ist Südkorea sicher für Reisende?","answer":"Ja, Südkorea zählt zu den sichersten Reiseländern mit sehr niedriger Kriminalität. Trotz der Nähe zu Nordkorea ist das Reisen im Land unbedenklich; man sollte lediglich die allgemeinen Hinweise des Auswärtigen Amts beachten."},{"question":"Wie viele Tage sollte man für Südkorea einplanen?","answer":"Für Seoul und Umgebung reichen einige Tage. Wer zusätzlich Busan, Gyeongju und die Insel Jeju erleben möchte, sollte 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Südkorea Urlaub: Seoul, Jeju, Reisetipps & beste Reisezeit$t$, $t$Dein Südkorea-Urlaub: das pulsierende Seoul, Busan, die Insel Jeju, die DMZ, K-Pop und koreanische Küche. Beste Reisezeit, Einreise ohne K-ETA, Highlights und Reisetipps im Überblick.$t$, $t$Südkorea Reise buchen, Flug nach Seoul, Hotel Seoul, Rundreise Südkorea, Städtereise Seoul, K-Pop Reise Korea$t$, false, $j$["japan","china","vietnam"]$j$::jsonb, ARRAY[$t$Südkorea$t$,$t$Seoul$t$,$t$Gyeongbokgung$t$,$t$Bukchon$t$,$t$Myeongdong$t$,$t$Gangnam$t$,$t$N Seoul Tower$t$,$t$Busan$t$,$t$Gamcheon Culture Village$t$,$t$Jeju$t$,$t$Hallasan$t$,$t$DMZ$t$,$t$Gyeongju$t$,$t$Bulguksa$t$,$t$K-Pop$t$,$t$Südkoreanischer Won$t$]::text[], $t$Südkorea ist ein dynamisches Reiseland in Ostasien zwischen Hightech und Tradition mit dem pulsierenden Seoul und seinen Palästen, der Hafenstadt Busan, der Vulkaninsel Jeju, der DMZ an der Grenze zu Nordkorea sowie der weltweit beliebten K-Pop-Kultur und exzellenter Küche. Dank hervorragendem Nahverkehr und KTX-Schnellzügen lässt es sich bequem bereisen und eignet sich ideal für Städte-, Kultur- und Kulinarikreisen. Deutsche reisen visumfrei und derzeit ohne K-ETA ein, müssen aber die e-Arrival Card ausfüllen.$t$, $t$Südkorea ist ein dynamisches Land mit dem pulsierenden Seoul, Busan, der Insel Jeju, der DMZ, K-Pop und exzellenter Küche – für Deutsche visumfrei und ohne K-ETA bereisbar.$t$, $t$https://www.apearound.de/reiseziele/suedkorea$t$, $t$/images/destinations/suedkorea.jpg$t$, $t$/images/destinations/suedkorea.jpg$t$, $t$Südkorea Urlaub: Seoul, Jeju, Reisetipps & beste Reisezeit$t$, $t$Dein Südkorea-Urlaub: das pulsierende Seoul, Busan, die Insel Jeju, die DMZ, K-Pop und koreanische Küche. Beste Reisezeit, Einreise ohne K-ETA, Highlights und Reisetipps im Überblick.$t$, $t$Südkorea Urlaub: Seoul, Jeju, Reisetipps & beste Reisezeit$t$, $t$Dein Südkorea-Urlaub: das pulsierende Seoul, Busan, die Insel Jeju, die DMZ, K-Pop und koreanische Küche. Beste Reisezeit, Einreise ohne K-ETA, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Thailand
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Thailand$t$, $t$thailand$t$, $t$Thailand$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/thailand-hero.jpg$t$, $t$Das beliebteste Fernreiseziel Südostasiens mit Traumstränden, glitzernden Tempeln, dem quirligen Bangkok, Dschungel im Norden und weltberühmter Küche.$t$, $t$Thailand ist das klassische Tor nach Südostasien und für viele die perfekte Mischung aus Strand, Kultur, Abenteuer und Genuss. Die pulsierende Hauptstadt Bangkok begeistert mit prachtvollen Tempeln wie dem Grand Palace und dem Wat Pho, lebhaften Märkten und einer überwältigenden Streetfood-Szene. Der Süden lockt mit den Traumstränden und Inseln der Andamansee und des Golfs von Thailand – von Phuket und den Kalksteinfelsen rund um Krabi und Railay über die Partyinsel Koh Phi Phi bis zu Koh Samui und der Taucherinsel Koh Tao. Im grünen Norden rund um Chiang Mai warten Bergtempel, ethische Elefanten-Schutzstationen und die Kultur der Bergvölker. Geschichtsfans erkunden die Ruinenstädte Ayutthaya und Sukhothai, Naturliebhaber den Regenwald des Khao-Sok-Nationalparks. Mit guter Infrastruktur, freundlichen Menschen und fairen Preisen ist Thailand ideal für Strandurlaub, Rundreisen, Backpacking und Familienreisen.$t$, $t$Thailand ist das beliebteste Fernreiseziel Südostasiens mit Traumstränden und Inseln im Süden, der Metropole Bangkok, dem grünen Norden rund um Chiang Mai und weltberühmter Küche. Es bietet eine gute Infrastruktur, faire Preise und eignet sich ideal für Strandurlaub, Rundreisen, Inselhüpfen und Familienreisen.$t$, $t$Die beste Reisezeit ist die kühle Trockenzeit von November bis März. Das Klima variiert regional: Die Andamanküste (Phuket, Krabi) ist im Winter ideal, während die Golfinseln wie Koh Samui eigene Regenmuster haben.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$Rundreise$t$,$t$Inselhüpfen$t$,$t$Backpacking$t$,$t$Kulturreise$t$,$t$Kulinarik$t$,$t$Familien$t$]::text[], $j${"currency":"Thailändischer Baht (THB)","language":"Thailändisch","flightTime":"ca. 10 bis 11 Stunden ab Deutschland im Direktflug (Bangkok)","timezone":"ICT (UTC+7), sechs Stunden vor MEZ","visa":"Für deutsche Staatsbürger visumfreier Aufenthalt bis 60 Tage; eine Verlängerung vor Ort ist möglich","bestMonths":"November bis März"}$j$::jsonb, $j$["Bangkok – Grand Palace, Wat Pho, Tempel, Märkte und Streetfood","Krabi und Railay – türkises Meer und spektakuläre Kalksteinfelsen","Phuket und Koh Phi Phi – Strände, Inselausflüge und Nachtleben","Koh Samui, Koh Phangan und Koh Tao – Golf-Inseln zum Baden und Tauchen","Chiang Mai – Bergtempel, Bergvölker und ethische Elefanten-Schutzstationen","Ayutthaya und Sukhothai – alte Königsstädte mit beeindruckenden Ruinen","Khao-Sok-Nationalpark – Regenwald, Kalksteinberge und Stausee","Schwimmende Märkte – farbenfrohes Treiben auf den Kanälen"]$j$::jsonb, $j$["Bei Elefanten-Erlebnissen unbedingt eine ethische Schutzstation ohne Reiten wählen, in der die Tiere artgerecht leben dürfen.","Echtes thailändisches Streetfood wie Pad Thai, Som Tam und Mango Sticky Rice schmeckt an den Garküchen am besten und ist sehr günstig.","Für den Transport in den Städten ist die Grab-App praktisch und transparent – sie zeigt den Preis vorab und vermeidet Verhandlungen.","Beim Besuch von Tempeln gilt ein Dresscode: Schultern und Knie sollten bedeckt sein, und die Schuhe werden vor dem Betreten ausgezogen."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Thailand?","answer":"Deutsche Staatsbürger können für touristische Aufenthalte bis zu 60 Tage visumfrei einreisen; eine Verlängerung ist vor Ort möglich. Der Reisepass muss bei Einreise noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Thailand?","answer":"Ideal ist die kühle Trockenzeit von November bis März. Das Klima ist jedoch regional unterschiedlich: Die Andamanküste rund um Phuket und Krabi ist im Winter am schönsten, während die Golfinseln wie Koh Samui ein etwas anderes Regenmuster haben."},{"question":"Welche Währung gilt in Thailand?","answer":"Gezahlt wird mit dem Thailändischen Baht (THB). Kartenzahlung ist in Städten und Hotels verbreitet, an Märkten und Garküchen ist jedoch Bargeld wichtig. Geldautomaten sind weit verfügbar."},{"question":"Wie reist man am besten innerhalb Thailands?","answer":"Günstige Inlandsflüge verbinden die Regionen schnell, dazu gibt es komfortable Züge, Busse und Fähren zu den Inseln. In Städten sind die Grab-App, Taxis und Tuk-Tuks praktisch. Ein eigener Mietwagen ist für die meisten Reisen nicht nötig."},{"question":"Sollte man in Thailand selbst Auto fahren?","answer":"Für die meisten Reisen ist es nicht nötig, da Flüge, Boote und Fahrdienste gut funktionieren. Wer dennoch fährt, sollte den Linksverkehr und den teils chaotischen Verkehr beachten; Roller sind beliebt, bergen aber ein hohes Unfallrisiko."},{"question":"Welche Inseln in Thailand sollte man besuchen?","answer":"Beliebt sind Phuket und Koh Phi Phi sowie Krabi mit Railay an der Andamanküste, dazu Koh Samui, Koh Phangan und die Taucherinsel Koh Tao im Golf von Thailand. Welche Inseln sich lohnen, hängt auch von der Reisezeit ab."},{"question":"Ist Thailand für einen Familienurlaub geeignet?","answer":"Ja, Thailand ist sehr familienfreundlich. Flache Strände, gute Hotels, kindgerechte Ausflüge, freundliche Menschen und vielfältiges Essen machen es zu einem beliebten Ziel für Familien."},{"question":"Kann man in Thailand das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden; in Restaurants und Hotels ist das üblich und problemlos verfügbar."},{"question":"Welche Impfungen werden für Thailand empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Welche Gerichte sollte man in Thailand probieren?","answer":"Unbedingt probieren sollte man Pad Thai, grünes und rotes Curry, Tom Yum (scharf-saure Suppe), Som Tam (Papayasalat) sowie Mango Sticky Rice als Dessert. Die thailändische Küche ist aromatisch und vielfältig."},{"question":"Ist Thailand sicher für Reisende?","answer":"Ja, Thailand gilt als sicheres und gut auf Touristen eingestelltes Reiseland. Aufpassen sollte man auf Taschendiebstahl, im Straßenverkehr sowie bei gängigen Touristenmaschen; Roller sollte man nur mit Erfahrung und Helm fahren."},{"question":"Wie viele Tage sollte man für Thailand einplanen?","answer":"Um Bangkok, den Norden und ein bis zwei Inseln zu verbinden, sind 2 bis 3 Wochen ideal. Für einen reinen Strandurlaub mit Bangkok-Stopp reichen auch rund 10 Tage."}]$j$::jsonb, $t$Thailand Urlaub: Strände, Bangkok, Reisetipps & beste Reisezeit$t$, $t$Dein Thailand-Urlaub: Traumstrände und Inseln, Bangkok, Chiang Mai und weltberühmte Küche. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Thailand Urlaub buchen, Flug nach Bangkok oder Phuket, Hotel Thailand, Rundreise Thailand, Inselhüpfen Thailand, Backpacking Südostasien, Strandurlaub Krabi$t$, false, $j$["vietnam","kambodscha","malaysia"]$j$::jsonb, ARRAY[$t$Thailand$t$,$t$Bangkok$t$,$t$Grand Palace$t$,$t$Wat Pho$t$,$t$Phuket$t$,$t$Krabi$t$,$t$Railay$t$,$t$Koh Phi Phi$t$,$t$Koh Samui$t$,$t$Koh Tao$t$,$t$Chiang Mai$t$,$t$Ayutthaya$t$,$t$Sukhothai$t$,$t$Khao-Sok-Nationalpark$t$,$t$Thailändischer Baht$t$,$t$Pad Thai$t$]::text[], $t$Thailand ist das beliebteste Fernreiseziel Südostasiens, bekannt für seine Traumstrände und Inseln im Süden, die pulsierende Metropole Bangkok mit ihren Tempeln, den grünen Norden rund um Chiang Mai und seine weltberühmte Küche. Mit guter Infrastruktur, fairen Preisen und freundlichen Menschen eignet es sich ideal für Strandurlaub, Rundreisen, Inselhüpfen und Familienreisen. Für deutsche Reisende ist ein Aufenthalt bis 60 Tage visumfrei, die beste Reisezeit liegt zwischen November und März.$t$, $t$Thailand ist das beliebteste Südostasien-Ziel mit Traumstränden, Inseln, der Metropole Bangkok und weltberühmter Küche, für Deutsche bis 60 Tage visumfrei.$t$, $t$https://www.apearound.de/reiseziele/thailand$t$, $t$/images/destinations/thailand.jpg$t$, $t$/images/destinations/thailand.jpg$t$, $t$Thailand Urlaub: Strände, Bangkok, Reisetipps & beste Reisezeit$t$, $t$Dein Thailand-Urlaub: Traumstrände und Inseln, Bangkok, Chiang Mai und weltberühmte Küche. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Thailand Urlaub: Strände, Bangkok, Reisetipps & beste Reisezeit$t$, $t$Dein Thailand-Urlaub: Traumstrände und Inseln, Bangkok, Chiang Mai und weltberühmte Küche. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Türkei
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Türkei$t$, $t$tuerkei$t$, $t$Türkei$t$, $t$Vorderasien$t$, $t$Europa/Asien$t$, $t$/images/destinations/tuerkei-hero.jpg$t$, $t$Brücke zwischen Europa und Asien mit dem faszinierenden Istanbul, der Märchenlandschaft Kappadokiens, antiken Stätten und der sonnenverwöhnten Türkischen Riviera.$t$, $t$Die Türkei vereint auf einzigartige Weise Orient und Okzident, Geschichte und Strandurlaub. Die Metropole Istanbul liegt auf zwei Kontinenten und beeindruckt mit der Hagia Sophia, der Blauen Moschee, dem Topkapı-Palast, dem Großen Basar und dem Treiben am Bosporus. Im Landesinneren erstreckt sich die surreale Märchenlandschaft Kappadokiens mit ihren Feenkaminen, Höhlenkirchen und den berühmten Heißluftballonfahrten bei Sonnenaufgang. Antike Höhepunkte wie die gut erhaltene Stadt Ephesus und die schneeweißen Kalksinterterrassen von Pamukkale ziehen Kulturreisende an. Vor allem aber ist die Türkei für ihre Küsten bekannt: Die Türkische Riviera rund um Antalya sowie die malerische Lykische Küste mit Orten wie Ölüdeniz und Kaş bieten Traumstrände, türkises Meer und komfortable All-Inclusive-Resorts. Dazu kommen die herzliche Gastfreundschaft, eine vielfältige Küche und ein gutes Preis-Leistungs-Verhältnis. Ideal für Strand-, Städte-, Kultur- und Rundreisen.$t$, $t$Die Türkei verbindet Europa und Asien und bietet die Metropole Istanbul, die Märchenlandschaft Kappadokiens, antike Stätten wie Ephesus und Pamukkale sowie die sonnenverwöhnte Türkische Riviera mit All-Inclusive-Resorts. Sie ist gastfreundlich, günstig und eignet sich ideal für Strand-, Städte-, Kultur- und Rundreisen.$t$, $t$April bis Juni sowie September und Oktober für Kultur und angenehme Temperaturen; die Küsten sind im Sommer ideal zum Baden, im Hochsommer wird es jedoch sehr heiß.$t$, $t$Strandurlaub 1 Woche, Rundreise 1 bis 2 Wochen$t$, ARRAY[$t$Strandurlaub$t$,$t$All-Inclusive$t$,$t$Städtereise$t$,$t$Kulturreise$t$,$t$Rundreise$t$,$t$Familien$t$,$t$Wellness$t$]::text[], $j${"currency":"Türkische Lira (TRY)","language":"Türkisch","flightTime":"ca. 3 bis 3,5 Stunden ab Deutschland (Istanbul, Antalya)","timezone":"TRT (UTC+3), zwei Stunden vor MEZ","visa":"Für deutsche Staatsbürger kein Visum nötig (Aufenthalt bis 90 Tage innerhalb von 180 Tagen)","bestMonths":"April bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Istanbul – Hagia Sophia, Blaue Moschee, Topkapı-Palast, Großer Basar und Bosporus","Kappadokien – Feenkamine, Höhlenkirchen und Heißluftballonfahrten bei Sonnenaufgang","Pamukkale – schneeweiße Kalksinterterrassen und das antike Hierapolis","Ephesus – eine der besterhaltenen antiken Städte der Welt","Türkische Riviera – Strände und Resorts rund um Antalya und Side","Lykische Küste – Ölüdeniz, Kaş und die berühmte Blaue Lagune","Bodrum und die Ägäisküste – lebendige Orte und schöne Buchten","Aspendos – beeindruckend erhaltenes römisches Theater"]$j$::jsonb, $j$["Eine Heißluftballonfahrt über Kappadokien bei Sonnenaufgang zählt zu den unvergesslichsten Erlebnissen einer Türkei-Reise – am besten frühzeitig buchen.","Auf den Basaren wie dem Großen Basar in Istanbul gehört freundliches Handeln zur Kultur – ein Tee und etwas Geduld führen oft zum besseren Preis.","Ein traditionelles türkisches Frühstück (Kahvaltı) mit vielen kleinen Speisen, dazu Çay und zum Abschluss Baklava, sollte man unbedingt probieren.","Für Istanbul sind Frühling und Herbst angenehmer als der heiße Hochsommer; die Küstenresorts lohnen sich dafür gerade in den Sommermonaten."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für die Türkei?","answer":"Nein, deutsche Staatsbürger benötigen für touristische Aufenthalte bis zu 90 Tage innerhalb von 180 Tagen kein Visum. Der Reisepass oder Personalausweis sollte für die Dauer des Aufenthalts gültig sein; für die Einreise wird in der Regel ein Reisepass empfohlen."},{"question":"Wann ist die beste Reisezeit für die Türkei?","answer":"Für Istanbul und Kulturreisen sind April bis Juni sowie September und Oktober ideal. Die Küsten eignen sich im Sommer zum Baden, wobei der Hochsommer an der Riviera sehr heiß werden kann."},{"question":"Welche Währung gilt in der Türkei?","answer":"Gezahlt wird mit der Türkischen Lira (TRY). In Resorts und touristischen Gebieten werden teils auch Euro akzeptiert. Wegen schwankender Kurse empfiehlt es sich, vor Ort in Lira zu zahlen und nur kleinere Beträge zu wechseln."},{"question":"Lohnt sich ein Mietwagen in der Türkei?","answer":"Für individuelle Rundreisen, etwa entlang der Lykischen Küste oder durch Kappadokien, ist ein Mietwagen sehr praktisch. In Istanbul ist er wegen des dichten Verkehrs nicht zu empfehlen; dort sind Metro, Tram und Fähren besser."},{"question":"Was kann man in Istanbul nicht verpassen?","answer":"Zu den Höhepunkten zählen die Hagia Sophia, die Blaue Moschee, der Topkapı-Palast, der Große Basar und der Gewürzbasar sowie eine Bosporus-Bootsfahrt zwischen Europa und Asien."},{"question":"Was macht Kappadokien besonders?","answer":"Kappadokien ist berühmt für seine surreale Landschaft aus Feenkaminen und Tuffsteinformationen, unterirdische Städte, in den Fels gehauene Kirchen und vor allem die spektakulären Heißluftballonfahrten am Morgen."},{"question":"Ist die Türkei gut für einen All-Inclusive-Urlaub?","answer":"Ja, die Türkische Riviera rund um Antalya, Side und Belek ist bekannt für ihre große Auswahl an komfortablen und oft preiswerten All-Inclusive-Resorts, ideal für einen entspannten Strand- und Familienurlaub."},{"question":"Ist die Türkei für einen Familienurlaub geeignet?","answer":"Ja, die Türkei ist sehr familienfreundlich. Flache Strände, familienorientierte Resorts mit Animation und Wasserparks sowie die herzliche Gastfreundschaft machen sie zu einem beliebten Familienziel."},{"question":"Welche Spezialitäten sollte man in der Türkei probieren?","answer":"Typisch sind Kebab in vielen Varianten, Meze, Gözleme, frischer Fisch an der Küste, das reichhaltige türkische Frühstück sowie Süßes wie Baklava und Lokum. Dazu gehören Çay und türkischer Mokka."},{"question":"Ist die Türkei sicher für Reisende?","answer":"Die klassischen Tourismusregionen wie Istanbul, die Riviera und Kappadokien gelten als gut bereisbar. Von Grenzregionen im Südosten wird abgeraten. Vor der Reise sollte man die aktuellen Hinweise des Auswärtigen Amts beachten."},{"question":"Wie viele Tage sollte man für die Türkei einplanen?","answer":"Für einen reinen Strandurlaub reicht eine Woche. Wer Istanbul, Kappadokien und antike Stätten verbinden möchte, sollte für eine Rundreise 1 bis 2 Wochen einplanen."}]$j$::jsonb, $t$Türkei Urlaub: Istanbul, Kappadokien, Strände & beste Reisezeit$t$, $t$Dein Türkei-Urlaub: das faszinierende Istanbul, die Märchenlandschaft Kappadokiens, antike Stätten wie Ephesus und Pamukkale sowie die Türkische Riviera. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Türkei Urlaub buchen, All-Inclusive Antalya, Flug und Hotel Istanbul, Rundreise Türkei, Ballonfahrt Kappadokien, Mietwagen Türkei vergleichen$t$, true, $j$["griechenland","aegypten","marokko"]$j$::jsonb, ARRAY[$t$Türkei$t$,$t$Istanbul$t$,$t$Hagia Sophia$t$,$t$Blaue Moschee$t$,$t$Topkapı-Palast$t$,$t$Bosporus$t$,$t$Kappadokien$t$,$t$Göreme$t$,$t$Pamukkale$t$,$t$Ephesus$t$,$t$Antalya$t$,$t$Türkische Riviera$t$,$t$Lykische Küste$t$,$t$Ölüdeniz$t$,$t$Bodrum$t$,$t$Türkische Lira$t$]::text[], $t$Die Türkei verbindet Europa und Asien und bietet die faszinierende Metropole Istanbul mit Hagia Sophia und Bosporus, die surreale Märchenlandschaft Kappadokiens mit ihren Ballonfahrten, antike Stätten wie Ephesus und Pamukkale sowie die sonnenverwöhnte Türkische Riviera mit All-Inclusive-Resorts. Das Land ist gastfreundlich, günstig und eignet sich ideal für Strand-, Städte-, Kultur- und Rundreisen. Für deutsche Reisende ist ein Aufenthalt bis 90 Tage visumfrei.$t$, $t$Die Türkei verbindet Europa und Asien mit Istanbul, der Märchenlandschaft Kappadokiens, antiken Stätten und der Türkischen Riviera, für Deutsche visumfrei.$t$, $t$https://www.apearound.de/reiseziele/tuerkei$t$, $t$/images/destinations/tuerkei.jpg$t$, $t$/images/destinations/tuerkei.jpg$t$, $t$Türkei Urlaub: Istanbul, Kappadokien, Strände & beste Reisezeit$t$, $t$Dein Türkei-Urlaub: das faszinierende Istanbul, die Märchenlandschaft Kappadokiens, antike Stätten wie Ephesus und Pamukkale sowie die Türkische Riviera. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Türkei Urlaub: Istanbul, Kappadokien, Strände & beste Reisezeit$t$, $t$Dein Türkei-Urlaub: das faszinierende Istanbul, die Märchenlandschaft Kappadokiens, antike Stätten wie Ephesus und Pamukkale sowie die Türkische Riviera. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Tunesien
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Tunesien$t$, $t$tunesien$t$, $t$Tunesien$t$, $t$Nordafrika$t$, $t$Afrika$t$, $t$/images/destinations/tunesien-hero.jpg$t$, $t$Sonnenziel am Mittelmeer mit weiten Sandstränden, antikem Karthago, dem blau-weißen Sidi Bou Saïd, der Sahara und günstigen All-Inclusive-Resorts.$t$, $t$Tunesien ist ein vielseitiges nordafrikanisches Reiseland und ein klassisches, gut erreichbares Sonnenziel am Mittelmeer. Lange Sandstrände und komfortable All-Inclusive-Resorts in Hammamet, Sousse und auf der Insel Djerba laden zum entspannten Badeurlaub ein. Doch Tunesien hat weit mehr zu bieten: In der Hauptstadt Tunis verzaubert die historische Medina, und ganz in der Nähe liegen die antiken Ruinen von Karthago sowie das malerische, blau-weiße Künstlerdorf Sidi Bou Saïd. Im Landesinneren beeindruckt das gewaltige römische Amphitheater von El Djem, und die heilige Stadt Kairouan mit ihrer großen Moschee zählt zu den bedeutendsten religiösen Orten der islamischen Welt. Im Süden beginnt die Sahara: Von Douz aus startet man zu Wüstentouren, und rund um Matmata und Tozeur erkennt man Drehorte der Star-Wars-Filme wieder. Mit orientalischem Flair, herzlicher Gastfreundschaft, würziger Küche und sehr günstigen Preisen ist Tunesien ideal für Strand-, Kultur- und Abenteuerurlaub.$t$, $t$Tunesien ist ein vielseitiges Sonnenziel am Mittelmeer mit langen Sandstränden und günstigen All-Inclusive-Resorts in Hammamet, Sousse und Djerba, dem antiken Karthago, dem blau-weißen Sidi Bou Saïd und der Sahara im Süden. Es ist gut erreichbar, preiswert und eignet sich ideal für Strand-, Kultur- und Wüstenreisen.$t$, $t$April bis Juni sowie September und Oktober für angenehme Temperaturen und Kultur; der Hochsommer ist ideal für den Badeurlaub, im Landesinneren und in der Sahara jedoch sehr heiß.$t$, $t$Strandurlaub 1 Woche, Rundreise 10 bis 14 Tage$t$, ARRAY[$t$Strandurlaub$t$,$t$All-Inclusive$t$,$t$Pauschalreise$t$,$t$Kulturreise$t$,$t$Wüstentour$t$,$t$Familien$t$,$t$Rundreise$t$]::text[], $j${"currency":"Tunesischer Dinar (TND); geschlossene Währung, die erst vor Ort gewechselt wird","language":"Arabisch; Französisch ist weit verbreitet","flightTime":"ca. 2,5 bis 3 Stunden ab Deutschland (Enfidha, Djerba, Tunis)","timezone":"UTC+1; im Winter gleich der MEZ, im Sommer eine Stunde zurück","visa":"Nicht erforderlich für deutsche Staatsbürger (Aufenthalt bis 90 Tage)","bestMonths":"April bis Juni sowie September und Oktober"}$j$::jsonb, $j$["Karthago – antike Ruinen der einstigen Großmacht bei Tunis, UNESCO-Welterbe","Sidi Bou Saïd – malerisches blau-weißes Künstlerdorf über dem Meer","Medina von Tunis – historische Altstadt mit Souks, UNESCO-Welterbe","Djerba – Sonneninsel mit Stränden und entspanntem Flair","El Djem – eines der besterhaltenen römischen Amphitheater der Welt","Kairouan – heilige Stadt mit der Großen Moschee, UNESCO-Welterbe","Sahara bei Douz – Tor zur Wüste für Kamelritte und Geländetouren","Matmata und Tozeur – Wüstenlandschaften und Star-Wars-Drehorte"]$j$::jsonb, $j$["Wer die Star-Wars-Filme mag, findet rund um Matmata, Tozeur und Ong Jemel originale Drehorte der Wüstenplaneten wieder.","Von Douz aus, dem „Tor zur Sahara“, lässt sich die Wüste bei einer Kamelritt- oder Jeep-Tour eindrucksvoll erleben.","Der Dinar ist eine geschlossene Währung: Am besten wechselt man erst vor Ort und gibt restliches Bargeld vor der Ausreise wieder aus.","Das blau-weiße Sidi Bou Saïd ist am frühen Morgen besonders fotogen und ruhig, bevor die Tagesausflügler eintreffen."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Tunesien?","answer":"Nein, deutsche Staatsbürger benötigen für touristische Aufenthalte bis zu 90 Tage kein Visum. Der Reisepass muss bei der Einreise noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Tunesien?","answer":"Für Kultur und Rundreisen sind Frühling (April bis Juni) und Herbst (September und Oktober) ideal. Der Hochsommer eignet sich für den Badeurlaub an der Küste, ist im Landesinneren und in der Sahara jedoch sehr heiß."},{"question":"Welche Währung gilt in Tunesien?","answer":"Gezahlt wird mit dem Tunesischen Dinar (TND). Es handelt sich um eine geschlossene Währung, die man im Ausland nicht bekommt und nicht ausführen darf. Am besten wechselt man vor Ort und gibt restliches Bargeld vor der Abreise aus."},{"question":"Ist Tunesien gut für einen All-Inclusive-Urlaub?","answer":"Ja, Tunesien ist für preiswerte All-Inclusive-Angebote bekannt. Beliebte Badeorte mit großer Resortauswahl sind Hammamet, Sousse, Monastir und die Insel Djerba."},{"question":"Sollte man in Tunesien selbst Auto fahren?","answer":"Viele Urlauber bleiben im Resort und nutzen organisierte Ausflüge, sodass ein Mietwagen nicht nötig ist. Für individuelle Rundreisen ist Selbstfahren möglich; in Städten und im Süden sind jedoch geführte Touren oder ein Fahrer oft entspannter."},{"question":"Wie sicher ist Tunesien für Reisende?","answer":"Die touristischen Regionen im Norden und an der Küste gelten als gut bereisbar. Von den Grenzgebieten zu Libyen und Algerien sowie Teilen der südlichen Wüste wird abgeraten. Vor der Reise sollte man die aktuellen Hinweise des Auswärtigen Amts prüfen."},{"question":"Kann man in Tunesien das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln sowie ungeschältem Obst vorsichtig sein."},{"question":"Wie erlebt man die Sahara in Tunesien?","answer":"Das Tor zur Wüste ist die Oasenstadt Douz, von der aus Kamelritte und Geländewagentouren starten. Rund um Tozeur, den Salzsee Chott el-Djerid und Matmata lassen sich faszinierende Wüstenlandschaften erkunden."},{"question":"Welche Kleidung ist in Tunesien angemessen?","answer":"An Stränden und in Resorts ist Badekleidung üblich. Außerhalb sowie an religiösen und kulturellen Stätten empfiehlt sich respektvolle, eher bedeckte Kleidung; in Moscheen sind Schultern und Knie zu bedecken."},{"question":"Welche Spezialitäten sollte man in Tunesien probieren?","answer":"Typisch sind Couscous, Brik (gefüllte, frittierte Teigtaschen), Tajine in tunesischer Variante, gegrillter Fisch sowie die scharfe Gewürzpaste Harissa. Dazu gehört süßer Minztee."},{"question":"Wie viele Tage sollte man für Tunesien einplanen?","answer":"Für einen reinen Strandurlaub reicht eine Woche. Wer Strand mit Kultur in Tunis und Karthago sowie der Sahara verbinden möchte, sollte 10 bis 14 Tage einplanen."}]$j$::jsonb, $t$Tunesien Urlaub: Strände, Karthago, Sahara & beste Reisezeit$t$, $t$Dein Tunesien-Urlaub: Sandstrände und All-Inclusive-Resorts, das antike Karthago, das blau-weiße Sidi Bou Saïd und die Sahara. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Tunesien Urlaub buchen, All-Inclusive Hammamet oder Djerba, Flug und Hotel Tunesien, Pauschalreise Tunesien, Wüstentour Sahara, Rundreise Tunesien$t$, false, $j$["marokko","aegypten","tuerkei"]$j$::jsonb, ARRAY[$t$Tunesien$t$,$t$Tunis$t$,$t$Karthago$t$,$t$Sidi Bou Saïd$t$,$t$Medina von Tunis$t$,$t$Djerba$t$,$t$El Djem$t$,$t$Kairouan$t$,$t$Sahara$t$,$t$Douz$t$,$t$Tozeur$t$,$t$Matmata$t$,$t$Chott el-Djerid$t$,$t$Hammamet$t$,$t$Sousse$t$,$t$Tunesischer Dinar$t$]::text[], $t$Tunesien ist ein vielseitiges Sonnenziel am Mittelmeer mit langen Sandstränden und günstigen All-Inclusive-Resorts in Hammamet, Sousse und auf Djerba, dem antiken Karthago, dem malerischen blau-weißen Sidi Bou Saïd und der Sahara im Süden. Das Land ist gut erreichbar, preiswert und bietet orientalisches Flair sowie herzliche Gastfreundschaft, ideal für Strand-, Kultur- und Wüstenreisen. Die beste Reisezeit liegt im Frühling und Herbst, für Badeurlaub auch im Sommer.$t$, $t$Tunesien ist ein günstiges Mittelmeerziel mit Sandstränden, dem antiken Karthago, dem blau-weißen Sidi Bou Saïd und der Sahara, ideal für Strand- und Kulturreisen.$t$, $t$https://www.apearound.de/reiseziele/tunesien$t$, $t$/images/destinations/tunesien.jpg$t$, $t$/images/destinations/tunesien.jpg$t$, $t$Tunesien Urlaub: Strände, Karthago, Sahara & beste Reisezeit$t$, $t$Dein Tunesien-Urlaub: Sandstrände und All-Inclusive-Resorts, das antike Karthago, das blau-weiße Sidi Bou Saïd und die Sahara. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$Tunesien Urlaub: Strände, Karthago, Sahara & beste Reisezeit$t$, $t$Dein Tunesien-Urlaub: Sandstrände und All-Inclusive-Resorts, das antike Karthago, das blau-weiße Sidi Bou Saïd und die Sahara. Beste Reisezeit, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Ungarn
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Ungarn$t$, $t$ungarn$t$, $t$Ungarn$t$, $t$Mitteleuropa$t$, $t$Europa$t$, $t$/images/destinations/ungarn-hero.jpg$t$, $t$Charmantes Nachbarland mit der prachtvollen Donaumetropole Budapest, historischen Thermalbädern, dem Plattensee und exzellentem Wein – günstig und nah.$t$, $t$Ungarn ist ein vielseitiges und für deutsche Reisende gut erreichbares Land im Herzen Mitteleuropas. Seine größte Attraktion ist die Hauptstadt Budapest, die sich beidseits der Donau erstreckt und mit dem majestätischen Parlamentsgebäude, dem Burgviertel, der Fischerbastei und der Kettenbrücke zu den schönsten Städten Europas zählt. Berühmt ist Budapest für seine historischen Thermalbäder wie das Széchenyi und das Gellért sowie für die lebendigen Ruinenbars im jüdischen Viertel. Außerhalb der Hauptstadt lockt der Plattensee (Balaton) als größter See Mitteleuropas zum Baden und Entspannen, während Weinregionen wie Eger mit seinem Stierblut und Tokaj mit seinen edlen Süßweinen Genießer anziehen. Charmante Städtchen wie Szentendre und Pécs sowie das malerische Donauknie runden das Bild ab. Mit reicher Kultur, deftiger Küche, Wellness-Tradition und fairen Preisen ist Ungarn ideal für Städtetrips, Kultur- und Wellnessreisen.$t$, $t$Ungarn ist ein charmantes mitteleuropäisches Reiseland mit der prachtvollen Donaumetropole Budapest, historischen Thermalbädern, dem Plattensee (Balaton) und renommierten Weinregionen wie Eger und Tokaj. Es ist schnell erreichbar, vergleichsweise günstig und eignet sich ideal für Städtetrips, Kultur- und Wellnessreisen.$t$, $t$Mai bis September für Städte und den Plattensee; Frühling und Herbst sind ideal für Budapest mit milderen Temperaturen, der Balaton ist im Sommer am attraktivsten.$t$, $t$Städtereise 3 bis 4 Tage, mit Plattensee bis zu einer Woche$t$, ARRAY[$t$Städtereise$t$,$t$Kulturreise$t$,$t$Wellness$t$,$t$Kulinarik$t$,$t$Familien$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Ungarischer Forint (HUF)","language":"Ungarisch","flightTime":"ca. 1,5 Stunden ab Deutschland (Budapest); aus Süddeutschland auch mit dem Auto erreichbar","timezone":"MEZ (UTC+1), identisch mit Deutschland","visa":"Nicht erforderlich für EU-Bürger (Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Budapest – Parlament, Burgviertel, Fischerbastei und die Kettenbrücke an der Donau","Thermalbäder – historische Bäder wie das Széchenyi und das Gellért","Ruinenbars – einzigartige Kneipen im jüdischen Viertel, etwa das Szimpla Kert","Plattensee (Balaton) – größter See Mitteleuropas zum Baden und Entspannen","Eger – Barockstadt, Burg und der berühmte Rotwein Stierblut","Tokaj – weltberühmte Weinregion für edle Süßweine","Donauknie – malerische Orte wie Visegrád, Esztergom und Szentendre","Pécs – Kunststadt im Süden mit mediterranem Flair"]$j$::jsonb, $j$["Ein Besuch in einem der historischen Thermalbäder, allen voran dem Széchenyi-Bad, gehört bei einer Budapest-Reise unbedingt dazu.","Die Ruinenbars im siebten Bezirk, wie das berühmte Szimpla Kert, sind abends ein einzigartiges Erlebnis aus Kneipe und Kunstinstallation.","Auch wenn an manchen Orten Euro akzeptiert wird, lohnt sich das Bezahlen in Forint, da der Wechselkurs sonst meist ungünstig ausfällt.","Unbedingt das Streetfood-Gericht Lángos sowie ein echtes ungarisches Gulasch probieren – am besten in einer einfachen, lokalen Gaststätte."]$j$::jsonb, $j$[{"question":"Welche Währung gilt in Ungarn?","answer":"In Ungarn zahlt man mit dem Ungarischen Forint (HUF), nicht mit dem Euro. Kartenzahlung ist weit verbreitet; wer bar zahlt, sollte dies in Forint tun, da der Euro-Kurs an Kassen meist ungünstig ist."},{"question":"Wann ist die beste Reisezeit für Ungarn?","answer":"Für Städtereisen nach Budapest sind Frühling und Herbst mit milden Temperaturen ideal. Der Plattensee ist im Sommer von Mai bis September am attraktivsten. Insgesamt ist die warme Jahreszeit am beliebtesten."},{"question":"Brauche ich ein Visum für Ungarn?","answer":"Nein. Ungarn ist EU- und Schengen-Mitglied, daher benötigen EU-Bürger kein Visum. Für die Einreise genügt ein gültiger Personalausweis oder Reisepass."},{"question":"Braucht man in Budapest ein Auto?","answer":"Nein, Budapest verfügt über ein hervorragendes Netz aus Metro, Straßenbahnen und Bussen, und vieles lässt sich zu Fuß erkunden. Ein Auto ist hier eher hinderlich; für Ausflüge an den Plattensee kann es jedoch praktisch sein."},{"question":"Sind die Thermalbäder in Budapest einen Besuch wert?","answer":"Ja, die Thermalbäder gehören zu den Wahrzeichen Budapests. Das Széchenyi-Bad mit seinen Außenbecken und das prachtvolle Gellért-Bad im Jugendstil sind besonders beliebt und ganzjährig geöffnet."},{"question":"Was kann man am Plattensee unternehmen?","answer":"Der Plattensee (Balaton) lädt zum Baden, Segeln und Radfahren ein. Beliebte Orte sind Siófok für Trubel, die Halbinsel Tihany mit ihrer Abtei sowie zahlreiche Weinorte am Nordufer."},{"question":"Ist Ungarn ein günstiges Reiseland?","answer":"Ja, im Vergleich zu Westeuropa sind Essen, Unterkünfte und Eintritte in Ungarn meist günstiger, was Budapest zu einem beliebten und preiswerten Städtereiseziel macht."},{"question":"Ist Ungarn für einen Familienurlaub geeignet?","answer":"Ja, Ungarn ist familienfreundlich. Der flache, warme Plattensee eignet sich gut zum Baden mit Kindern, dazu gibt es Thermalbäder mit Erlebnisbereichen, Burgen und kindgerechte Ausflugsziele."},{"question":"Welche Spezialitäten sollte man in Ungarn probieren?","answer":"Typisch sind Gulasch (als Suppe), Pörkölt, Lángos (frittierter Teigfladen), Paprikahähnchen sowie zum Dessert Dobostorte. Dazu passen ungarische Weine aus Eger oder Tokaj."},{"question":"Spricht man in Ungarn Deutsch oder Englisch?","answer":"In Budapest und touristischen Orten kommt man mit Englisch und oft auch Deutsch gut zurecht. Auf dem Land sind Sprachkenntnisse seltener; Ungarisch selbst ist mit anderen europäischen Sprachen kaum verwandt."},{"question":"Wie viele Tage sollte man für Ungarn einplanen?","answer":"Für Budapest reichen 3 bis 4 Tage. Wer zusätzlich den Plattensee, das Donauknie oder eine Weinregion erleben möchte, sollte bis zu einer Woche einplanen."}]$j$::jsonb, $t$Ungarn Urlaub: Budapest, Plattensee, Tipps & beste Reisezeit$t$, $t$Dein Ungarn-Urlaub: die Donaumetropole Budapest, historische Thermalbäder, der Plattensee und Weinregionen wie Eger und Tokaj. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Ungarn Reise buchen, Städtereise Budapest, Hotel Budapest, Wellnessurlaub Thermalbad Ungarn, Ferienhaus Plattensee, Wochenendtrip Budapest$t$, false, $j$["tschechien","oesterreich","slowakei"]$j$::jsonb, ARRAY[$t$Ungarn$t$,$t$Budapest$t$,$t$Donau$t$,$t$Parlament Budapest$t$,$t$Fischerbastei$t$,$t$Kettenbrücke$t$,$t$Széchenyi-Bad$t$,$t$Gellért-Bad$t$,$t$Ruinenbars$t$,$t$Szimpla Kert$t$,$t$Plattensee$t$,$t$Balaton$t$,$t$Eger$t$,$t$Tokaj$t$,$t$Ungarischer Forint$t$,$t$Gulasch$t$]::text[], $t$Ungarn ist ein charmantes mitteleuropäisches Reiseland mit der prachtvollen Donaumetropole Budapest, ihren historischen Thermalbädern und Ruinenbars, dem Plattensee (Balaton) als größtem See Mitteleuropas sowie renommierten Weinregionen wie Eger und Tokaj. Das Land ist von Deutschland aus schnell erreichbar, vergleichsweise günstig und eignet sich ideal für Städtetrips, Kultur- und Wellnessreisen. Gezahlt wird mit dem Forint, die beste Reisezeit liegt zwischen Mai und September.$t$, $t$Ungarn ist ein günstiges mitteleuropäisches Reiseland mit der Donaumetropole Budapest, historischen Thermalbädern, dem Plattensee und edlen Weinen.$t$, $t$https://www.apearound.de/reiseziele/ungarn$t$, $t$/images/destinations/ungarn.jpg$t$, $t$/images/destinations/ungarn.jpg$t$, $t$Ungarn Urlaub: Budapest, Plattensee, Tipps & beste Reisezeit$t$, $t$Dein Ungarn-Urlaub: die Donaumetropole Budapest, historische Thermalbäder, der Plattensee und Weinregionen wie Eger und Tokaj. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$Ungarn Urlaub: Budapest, Plattensee, Tipps & beste Reisezeit$t$, $t$Dein Ungarn-Urlaub: die Donaumetropole Budapest, historische Thermalbäder, der Plattensee und Weinregionen wie Eger und Tokaj. Beste Reisezeit, Highlights und Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Vietnam
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Vietnam$t$, $t$vietnam$t$, $t$Vietnam$t$, $t$Südostasien$t$, $t$Asien$t$, $t$/images/destinations/vietnam-hero.jpg$t$, $t$Faszinierendes Südostasien-Ziel mit der Halong-Bucht, Reisterrassen, quirligen Städten, Laternendörfern, Traumstränden und weltberühmter Küche.$t$, $t$Vietnam ist eines der vielfältigsten und faszinierendsten Reiseländer Südostasiens und erstreckt sich schmal über mehr als 1.600 Kilometer von Norden nach Süden. Im Norden beeindrucken die smaragdgrünen Karstfelsen der Halong-Bucht, die leuchtenden Reisterrassen rund um Sapa und die quirlige Altstadt der Hauptstadt Hanoi. Die Landesmitte besticht mit der charmanten Laternenstadt Hoi An, der kaiserlichen Geschichte von Hue und den gewaltigen Höhlen von Phong Nha. Im Süden pulsiert die Millionenmetropole Ho-Chi-Minh-Stadt (Saigon), während das Mekong-Delta mit schwimmenden Märkten und üppigem Grün lockt. Dazu kommen die Traumstrände der Insel Phu Quoc. Vietnam ist berühmt für seine frische, aromatische Küche mit Klassikern wie Pho und Banh Mi, für seine herzlichen Menschen und für ein hervorragendes Preis-Leistungs-Verhältnis. Ob Rundreise, Kultur, Natur oder Strand – das Land bietet intensive und abwechslungsreiche Erlebnisse.$t$, $t$Vietnam ist ein vielseitiges Reiseland in Südostasien mit der Halong-Bucht, den Reisterrassen von Sapa, den Städten Hanoi und Ho-Chi-Minh-Stadt, der Laternenstadt Hoi An und dem Mekong-Delta. Es ist bekannt für seine Küche, Gastfreundschaft und günstige Preise und eignet sich ideal für Rundreisen, Kultur-, Natur- und Strandurlaube.$t$, $t$Aufgrund der Länge des Landes variiert das Klima stark; insgesamt sind die Monate November bis April günstig. Der Norden ist im Frühjahr und Herbst am angenehmsten, der Süden ganzjährig warm mit Trockenzeit von Dezember bis April.$t$, $t$2 bis 3 Wochen$t$, ARRAY[$t$Rundreise$t$,$t$Kulturreise$t$,$t$Naturreise$t$,$t$Strandurlaub$t$,$t$Backpacking$t$,$t$Kulinarik$t$,$t$Abenteuer$t$]::text[], $j${"currency":"Vietnamesischer Dong (VND)","language":"Vietnamesisch","flightTime":"ca. 11 bis 13 Stunden ab Deutschland, meist mit Zwischenstopp (Hanoi, Ho-Chi-Minh-Stadt)","timezone":"ICT (UTC+7), sechs Stunden vor MEZ","visa":"Für deutsche Staatsbürger visumfreier Aufenthalt bis 45 Tage; für längere Aufenthalte ist ein E-Visum (bis 90 Tage) erhältlich","bestMonths":"November bis April"}$j$::jsonb, $j$["Halong-Bucht – smaragdgrünes Meer mit tausenden Karstfelsen, UNESCO-Welterbe","Hanoi – lebendige Altstadt, Seen und französisches Kolonialerbe","Hoi An – romantische Laternenstadt mit gut erhaltener Altstadt","Sapa – terrassierte Reisfelder und Bergvölker im Norden","Ho-Chi-Minh-Stadt (Saigon) – pulsierende Metropole im Süden","Mekong-Delta – schwimmende Märkte und üppige Wasserlandschaft","Hue – ehemalige Kaiserstadt mit Zitadelle und Königsgräbern","Phong Nha und Ninh Binh – spektakuläre Höhlen und „Halong an Land“"]$j$::jsonb, $j$["Das beste Essen findet man an den Straßenständen – Klassiker wie Pho, Banh Mi und Bun Cha sind dort am authentischsten und günstigsten.","Beim Überqueren der von Rollern gefüllten Straßen hilft es, ruhig und gleichmäßig weiterzugehen, statt stehen zu bleiben – der Verkehr fließt um einen herum.","Für die Halong-Bucht lohnt sich eine Übernachtung an Bord eines Bootes; die benachbarte Lan-Ha-Bucht ist oft ruhiger und weniger überlaufen.","Da der Norden und der Süden sehr unterschiedliches Klima haben, sollte man je nach Route sowohl leichte Kleidung als auch etwas Wärmeres einpacken."]$j$::jsonb, $j$[{"question":"Brauche ich ein Visum für Vietnam?","answer":"Deutsche Staatsbürger können für touristische Aufenthalte bis zu 45 Tage visumfrei einreisen. Für längere Aufenthalte gibt es ein praktisches E-Visum, das online beantragt werden kann und bis zu 90 Tage gültig ist. Der Reisepass muss noch mindestens sechs Monate gültig sein."},{"question":"Wann ist die beste Reisezeit für Vietnam?","answer":"Da sich Vietnam über mehr als 1.600 Kilometer erstreckt, unterscheidet sich das Klima stark. Insgesamt sind November bis April günstig. Der Norden ist im Frühjahr und Herbst am schönsten, der Süden ganzjährig warm mit Trockenzeit von Dezember bis April."},{"question":"Welche Währung gilt in Vietnam?","answer":"Gezahlt wird mit dem Vietnamesischen Dong (VND). In Städten ist Kartenzahlung zunehmend möglich, dennoch ist Bargeld besonders an Märkten und Straßenständen wichtig. Es empfiehlt sich, kleine Scheine bereitzuhalten."},{"question":"Wie reist man am besten innerhalb Vietnams?","answer":"Für lange Strecken eignen sich Inlandsflüge, Nachtzüge wie der Reunification Express und komfortable Busse. Vor Ort nutzt man Taxis, App-Fahrdienste und Roller-Taxis. Ein eigener Mietwagen ist wegen des dichten Verkehrs nicht zu empfehlen; üblicher ist ein Privatfahrer."},{"question":"Kann man in Vietnam selbst Auto fahren?","answer":"Davon ist abzuraten. Der Verkehr ist dicht und unübersichtlich, und für ausländische Führerscheine gelten besondere Regelungen. Praktischer und sicherer ist es, einen Wagen mit Fahrer zu buchen oder öffentliche Verkehrsmittel zu nutzen."},{"question":"Ist Vietnam ein günstiges Reiseland?","answer":"Ja, Vietnam zählt zu den preiswertesten Reiseländern Asiens. Essen, Unterkünfte und Transport sind sehr günstig, was es besonders für Rundreisen und Backpacking attraktiv macht."},{"question":"Kann man in Vietnam das Leitungswasser trinken?","answer":"Nein, das Leitungswasser ist nicht zum Trinken geeignet. Man sollte abgefülltes Wasser verwenden und bei Eiswürfeln und rohen Speisen vorsichtig sein, um Magenproblemen vorzubeugen."},{"question":"Welche Impfungen werden für Vietnam empfohlen?","answer":"Vorgeschrieben sind in der Regel keine Impfungen. Empfohlen werden Standardimpfungen sowie je nach Reiseart Hepatitis A und teils Typhus. Für eine individuelle Beratung sollte man rechtzeitig ein Tropeninstitut oder den Hausarzt aufsuchen."},{"question":"Welche Spezialitäten sollte man in Vietnam probieren?","answer":"Unbedingt probieren sollte man Pho (Nudelsuppe), Banh Mi (gefülltes Baguette), Bun Cha, frische Sommerrollen sowie den starken vietnamesischen Kaffee, etwa als Egg Coffee oder mit Kondensmilch."},{"question":"Ist Vietnam für einen Familienurlaub geeignet?","answer":"Ja, Vietnam ist familienfreundlich und sicher. Bootsfahrten in der Halong-Bucht, Strände auf Phu Quoc, freundliche Menschen und vielfältiges Essen begeistern auch Kinder. Für lange Strecken sollte man etwas mehr Reisezeit einplanen."},{"question":"Ist Vietnam sicher für Reisende?","answer":"Ja, Vietnam gilt als sicheres Reiseland mit niedriger Gewaltkriminalität. Aufpassen sollte man vor allem auf Taschendiebstahl in Großstädten sowie im chaotischen Straßenverkehr."},{"question":"Wie viele Tage sollte man für Vietnam einplanen?","answer":"Um Norden, Mitte und Süden zu verbinden, sind 2 bis 3 Wochen ideal. Für eine einzelne Region wie den Norden mit Hanoi und der Halong-Bucht reicht etwa eine Woche."}]$j$::jsonb, $t$Vietnam Urlaub: Halong-Bucht, Rundreise, Tipps & beste Reisezeit$t$, $t$Dein Vietnam-Urlaub: Halong-Bucht, Reisterrassen in Sapa, Hanoi, Hoi An und das Mekong-Delta. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Vietnam Rundreise buchen, Flug nach Hanoi oder Ho-Chi-Minh-Stadt, Halong-Bucht Kreuzfahrt, Hotel Vietnam, Backpacking Südostasien, Strandurlaub Phu Quoc$t$, false, $j$["thailand","kambodscha","laos"]$j$::jsonb, ARRAY[$t$Vietnam$t$,$t$Halong-Bucht$t$,$t$Hanoi$t$,$t$Ho-Chi-Minh-Stadt$t$,$t$Saigon$t$,$t$Hoi An$t$,$t$Sapa$t$,$t$Mekong-Delta$t$,$t$Hue$t$,$t$Phong Nha$t$,$t$Ninh Binh$t$,$t$Phu Quoc$t$,$t$Pho$t$,$t$Banh Mi$t$,$t$Vietnamesischer Dong$t$,$t$Reisterrassen$t$]::text[], $t$Vietnam ist ein vielseitiges Reiseland in Südostasien, bekannt für die smaragdgrüne Halong-Bucht, die Reisterrassen von Sapa, die Städte Hanoi und Ho-Chi-Minh-Stadt, die Laternenstadt Hoi An und das Mekong-Delta. Das Land begeistert mit weltberühmter Küche, herzlicher Gastfreundschaft und günstigen Preisen und eignet sich ideal für Rundreisen, Kultur-, Natur- und Strandurlaube. Für deutsche Reisende ist ein Aufenthalt bis 45 Tage visumfrei möglich.$t$, $t$Vietnam ist ein vielseitiges Südostasien-Ziel mit der Halong-Bucht, Reisterrassen, lebendigen Städten und weltberühmter Küche, für Deutsche bis 45 Tage visumfrei.$t$, $t$https://www.apearound.de/reiseziele/vietnam$t$, $t$/images/destinations/vietnam.jpg$t$, $t$/images/destinations/vietnam.jpg$t$, $t$Vietnam Urlaub: Halong-Bucht, Rundreise, Tipps & beste Reisezeit$t$, $t$Dein Vietnam-Urlaub: Halong-Bucht, Reisterrassen in Sapa, Hanoi, Hoi An und das Mekong-Delta. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$Vietnam Urlaub: Halong-Bucht, Rundreise, Tipps & beste Reisezeit$t$, $t$Dein Vietnam-Urlaub: Halong-Bucht, Reisterrassen in Sapa, Hanoi, Hoi An und das Mekong-Delta. Beste Reisezeit, Visum, Highlights und praktische Reisetipps im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Wuppertal
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Wuppertal$t$, $t$wuppertal$t$, $t$Deutschland$t$, $t$Nordrhein-Westfalen$t$, $t$Europa$t$, $t$/images/destinations/wuppertal-hero.jpg$t$, $t$Bergische Großstadt mit der weltberühmten Schwebebahn, grünem Zoo, kreativer Kulturszene und der Nordbahntrasse als Rad- und Wanderparadies.$t$, $t$Wuppertal im Bergischen Land ist vor allem für ein einzigartiges Wahrzeichen bekannt: die Schwebebahn, die seit über 120 Jahren schwebend über dem Fluss Wupper durch die Stadt gleitet und weltweit ihresgleichen sucht. Eine Fahrt damit ist das ultimative Wuppertal-Erlebnis. Doch die Stadt hat mehr zu bieten: Der Grüne Zoo zählt zu den schönsten Tierparks Deutschlands und ist eng mit der berühmten Geschichte der Elefantendame Tuffi verbunden. Auf der Nordbahntrasse, einer zur Rad- und Wanderstrecke umgebauten Bahnlinie, erkundet man die Stadt von oben, vorbei an Tunneln und Vierteln. Kulturell ist Wuppertal die Heimat des weltberühmten Tanztheaters von Pina Bausch, beherbergt das renommierte Von der Heydt-Museum und den Skulpturenpark Waldfrieden des Künstlers Tony Cragg. Als Geburtsstadt von Friedrich Engels und mit dem lebendigen Luisenviertel sowie prächtigen Gründerzeitvillen verbindet Wuppertal Industriegeschichte, Kunst und Natur zu einem überraschend vielseitigen Ziel für einen Tagesausflug oder Kurztrip.$t$, $t$Wuppertal ist eine Großstadt im Bergischen Land, berühmt für die einzigartige Schwebebahn, den Grünen Zoo, die Nordbahntrasse zum Radfahren und eine lebendige Kulturszene mit dem Tanztheater Pina Bausch und dem Skulpturenpark Waldfrieden. Die Stadt eignet sich ideal für einen Tagesausflug oder Kurztrip.$t$, $t$Mai bis September für mildes Wetter, die Nordbahntrasse, den Zoo und die grünen Außenbereiche; die Innenstadt und Museen sind ganzjährig attraktiv.$t$, $t$1 bis 2 Tage$t$, ARRAY[$t$Städtereise$t$,$t$Tagesausflug$t$,$t$Kulturreise$t$,$t$Familien$t$,$t$Wochenendtrip$t$]::text[], $j${"currency":"Euro (EUR)","language":"Deutsch","flightTime":"Innerdeutsch per Bahn oder Auto erreichbar; nächste Flughäfen sind Düsseldorf und Köln/Bonn","timezone":"MEZ (UTC+1)","visa":"Nicht erforderlich (Inland für Deutsche, EU- und Schengen-Raum)","bestMonths":"Mai bis September"}$j$::jsonb, $j$["Schwebebahn – das einzigartige Wahrzeichen, schwebend über der Wupper","Grüner Zoo Wuppertal – einer der schönsten Tierparks Deutschlands","Nordbahntrasse – Rad- und Wanderweg auf einer ehemaligen Bahnlinie","Skulpturenpark Waldfrieden – moderne Kunst des Bildhauers Tony Cragg","Von der Heydt-Museum – renommierte Kunstsammlung in der Innenstadt","Tanztheater Pina Bausch – weltberühmte Wuppertaler Tanzkompanie","Botanischer Garten mit Elisenturm – grüne Oase mit Aussicht","Luisenviertel – lebendiges Gründerzeitviertel mit Cafés und Kneipen"]$j$::jsonb, $j$["Eine Fahrt mit der Schwebebahn gehört unbedingt dazu – am eindrucksvollsten ist die Strecke über dem Fluss Wupper.","Die Nordbahntrasse lässt sich wunderbar mit dem Rad erkunden und verbindet auf ebener Strecke mehrere Stadtteile, Tunnel und Aussichtspunkte.","Im Luisenviertel findet man die schönste Gastronomie der Stadt – ideal für eine Pause oder den Abend.","Wer Zeit hat, sollte eine echte Bergische Kaffeetafel mit Waffeln, Reibekuchen und der typischen Dröppelmina-Kanne probieren."]$j$::jsonb, $j$[{"question":"Was ist die Wuppertaler Schwebebahn?","answer":"Die Schwebebahn ist eine seit 1901 betriebene Hängebahn, die auf rund 13 Kilometern größtenteils über dem Fluss Wupper schwebt. Sie ist das Wahrzeichen der Stadt, ein einzigartiges Verkehrsmittel und zugleich eine echte Attraktion."},{"question":"Lohnt sich ein Ausflug nach Wuppertal?","answer":"Ja, Wuppertal eignet sich gut für einen Tagesausflug oder Kurztrip. Eine Schwebebahnfahrt, der Grüne Zoo, die Nordbahntrasse und die Kulturangebote bieten viel Abwechslung auf kompaktem Raum."},{"question":"Wann ist die beste Reisezeit für Wuppertal?","answer":"Von Mai bis September lassen sich die Nordbahntrasse, der Zoo und die grünen Außenbereiche am besten genießen. Die Innenstadt, Museen und die Schwebebahn sind jedoch ganzjährig einen Besuch wert."},{"question":"Wie kommt man nach Wuppertal?","answer":"Wuppertal ist innerdeutsch sehr gut per Bahn und Auto erreichbar und liegt zentral im Ruhrgebiet- und Rheinland-Umfeld. Die nächsten Flughäfen sind Düsseldorf und Köln/Bonn, beide nur eine kurze Fahrt entfernt."},{"question":"Braucht man in Wuppertal ein Auto?","answer":"Nein. Mit der Schwebebahn, Bussen und der Bahn ist man gut unterwegs, und viele Sehenswürdigkeiten liegen zentral. Ein Auto ist nicht nötig, kann aber für Ausflüge ins Bergische Land praktisch sein."},{"question":"Ist der Grüne Zoo Wuppertal einen Besuch wert?","answer":"Ja, der Grüne Zoo gilt als einer der schönsten Tierparks Deutschlands, eingebettet in eine parkartige Hanglage mit altem Baumbestand. Er ist besonders für Familien ein lohnendes Ziel."},{"question":"Was ist die Nordbahntrasse?","answer":"Die Nordbahntrasse ist eine zur Rad- und Wanderstrecke umgebaute ehemalige Bahnlinie, die auf rund 23 Kilometern weitgehend steigungsarm durch Wuppertal führt – vorbei an Tunneln, Vierteln und Aussichtspunkten."},{"question":"Welche kulturellen Highlights bietet Wuppertal?","answer":"Wuppertal ist die Heimat des weltberühmten Tanztheaters von Pina Bausch, beherbergt das Von der Heydt-Museum und den Skulpturenpark Waldfrieden des Bildhauers Tony Cragg. Zudem ist es die Geburtsstadt von Friedrich Engels."},{"question":"Ist Wuppertal für Familien geeignet?","answer":"Ja, sehr. Die Schwebebahnfahrt begeistert Kinder, der Grüne Zoo, die Nordbahntrasse und Parks bieten viel Platz, und es gibt zahlreiche familienfreundliche Ausflugsziele in und um die Stadt."},{"question":"Wie viele Tage sollte man für Wuppertal einplanen?","answer":"Für die wichtigsten Highlights reicht ein Tag. Wer Kultur, Zoo, Nordbahntrasse und die Viertel in Ruhe erleben möchte, plant am besten ein Wochenende ein."}]$j$::jsonb, $t$Wuppertal: Schwebebahn, Sehenswürdigkeiten & Ausflugstipps$t$, $t$Dein Ausflug nach Wuppertal: die weltberühmte Schwebebahn, der Grüne Zoo, die Nordbahntrasse und eine kreative Kulturszene. Sehenswürdigkeiten, Tipps und beste Reisezeit im Überblick.$t$, $t$Wuppertal Ausflug, Hotel Wuppertal, Schwebebahn fahren, Städtetrip Bergisches Land, Wochenendtrip NRW, Wuppertal mit Kindern$t$, false, $j$["duesseldorf","koeln","dortmund"]$j$::jsonb, ARRAY[$t$Wuppertal$t$,$t$Schwebebahn$t$,$t$Wupper$t$,$t$Grüner Zoo Wuppertal$t$,$t$Tuffi$t$,$t$Nordbahntrasse$t$,$t$Skulpturenpark Waldfrieden$t$,$t$Tony Cragg$t$,$t$Von der Heydt-Museum$t$,$t$Pina Bausch$t$,$t$Tanztheater Wuppertal$t$,$t$Friedrich Engels$t$,$t$Luisenviertel$t$,$t$Botanischer Garten$t$,$t$Bergisches Land$t$]::text[], $t$Wuppertal ist eine Großstadt im Bergischen Land, weltberühmt für die einzigartige Schwebebahn, die schwebend über dem Fluss Wupper durch die Stadt gleitet. Dazu kommen der schöne Grüne Zoo, die Nordbahntrasse zum Radfahren und Wandern sowie eine lebendige Kulturszene mit dem Tanztheater Pina Bausch und dem Skulpturenpark Waldfrieden. Die Stadt ist innerdeutsch gut erreichbar und eignet sich ideal für einen Tagesausflug oder Kurztrip.$t$, $t$Wuppertal ist eine Stadt im Bergischen Land mit der weltberühmten Schwebebahn, dem Grünen Zoo und der Nordbahntrasse, ideal für einen Tagesausflug.$t$, $t$https://www.apearound.de/reiseziele/wuppertal$t$, $t$/images/destinations/wuppertal.jpg$t$, $t$/images/destinations/wuppertal.jpg$t$, $t$Wuppertal: Schwebebahn, Sehenswürdigkeiten & Ausflugstipps$t$, $t$Dein Ausflug nach Wuppertal: die weltberühmte Schwebebahn, der Grüne Zoo, die Nordbahntrasse und eine kreative Kulturszene. Sehenswürdigkeiten, Tipps und beste Reisezeit im Überblick.$t$, $t$Wuppertal: Schwebebahn, Sehenswürdigkeiten & Ausflugstipps$t$, $t$Dein Ausflug nach Wuppertal: die weltberühmte Schwebebahn, der Grüne Zoo, die Nordbahntrasse und eine kreative Kulturszene. Sehenswürdigkeiten, Tipps und beste Reisezeit im Überblick.$t$, $t$draft$t$)
