-- Yellowstone-Nationalpark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Yellowstone-Nationalpark$t$, $t$yellowstone$t$, $t$Vereinigte Staaten (USA)$t$, $t$Wyoming, Montana und Idaho$t$, $t$Nordamerika$t$, $t$/images/destinations/yellowstone-hero.jpg$t$, $t$Der älteste Nationalpark der Welt im US-Westen mit brodelnden Geysiren, regenbogenfarbenen heißen Quellen, gewaltigen Wasserfällen und freilebenden Bisons, Bären und Wölfen.$t$, $t$Der 1872 gegründete Yellowstone-Nationalpark ist der älteste Nationalpark der Welt und eines der spektakulärsten Naturwunder der USA. Er liegt überwiegend in Wyoming und reicht bis nach Montana und Idaho – und thront auf einem gewaltigen Supervulkan, dessen Hitze die einzigartige geothermale Landschaft speist. Das Wahrzeichen ist der Geysir Old Faithful, der zuverlässig in die Höhe schießt. Die Grand Prismatic Spring leuchtet in unwirklichen Regenbogenfarben, die Sinterterrassen von Mammoth Hot Springs und die dampfenden Becken des Norris Geyser Basin faszinieren ebenso wie der farbenprächtige Grand Canyon of the Yellowstone mit seinen tosenden Wasserfällen. Yellowstone ist außerdem eines der besten Wildtiergebiete Nordamerikas: In den weiten Tälern Lamar und Hayden beobachtet man Bisonherden, Wapitis, Grizzlys, Schwarzbären und Wölfe. Direkt im Süden schließt der Grand-Teton-Nationalpark mit seiner dramatischen Bergkulisse an. Yellowstone ist ideal als Höhepunkt eines Roadtrips durch den amerikanischen Westen und ein Traumziel für Natur-, Wander- und Fotoreisen.$t$, $t$Der Yellowstone-Nationalpark im US-Westen (überwiegend Wyoming) ist der älteste Nationalpark der Welt, berühmt für Geysire wie Old Faithful, die Grand Prismatic Spring, Wasserfälle und reiche Tierwelt mit Bisons, Bären und Wölfen. Er eignet sich ideal als Höhepunkt eines USA-Westen-Roadtrips und für Natur- und Wanderreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Juni bis September für offene Straßen, mildes Wetter und beste Tierbeobachtung; viele Parkstraßen sind etwa von November bis April geschlossen, im Winter ist der Park nur eingeschränkt per Snowcoach erreichbar.$t$, $t$3 bis 5 Tage, oft als Teil eines größeren West-Roadtrips$t$, ARRAY[$t$Naturreise$t$,$t$Nationalparks$t$,$t$Roadtrip$t$,$t$Wandern$t$,$t$Tierbeobachtung$t$,$t$Abenteuer$t$,$t$Familien$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch","flightTime":"Kein Direktflug; ab Deutschland ca. 11 bis 13 Stunden in die USA plus Inlandsanschluss. Nächste Flughäfen: Bozeman (BZN), Jackson Hole (JAC) und Cody (COD)","timezone":"Mountain Time (UTC−7; im Sommer UTC−6), rund acht Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"Juni bis September"}$j$::jsonb, $j$["Old Faithful – der berühmteste und besonders zuverlässige Geysir des Parks","Grand Prismatic Spring – größte heiße Quelle der USA in leuchtenden Regenbogenfarben","Grand Canyon of the Yellowstone – farbige Schlucht mit den tosenden Lower Falls","Lamar Valley und Hayden Valley – beste Gebiete für Bisons, Bären und Wölfe","Mammoth Hot Springs – terrassenförmige Kalksinterformationen","Norris Geyser Basin – heißestes und dynamischstes Geysirfeld des Parks","Yellowstone Lake – großer Bergsee inmitten der Wildnis","Grand-Teton-Nationalpark – dramatische Bergkette direkt südlich, ideal zum Kombinieren"]$j$::jsonb, $j$["Unterkünfte in den Park-Lodges und die Campgrounds sind extrem begehrt – am besten viele Monate im Voraus reservieren; alternativ in Gateway-Towns wie West Yellowstone oder Gardiner übernachten.","Wildtiere beobachtet man am besten früh morgens oder am Abend in den Tälern Lamar und Hayden – stets großen Abstand halten (mind. 91 m zu Bären und Wölfen, 23 m zu Bisons und Wapitis) und Bärenspray mitführen.","Die nächste Eruptionszeit von Old Faithful wird am Visitor Center und in der offiziellen NPS-App angezeigt – so vermeidet man langes Warten.","Yellowstone lässt sich hervorragend mit dem direkt angrenzenden Grand-Teton-Nationalpark zu einer Rundreise verbinden."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für den Yellowstone-Nationalpark?","answer":"Die beste Zeit ist von Juni bis September, wenn alle Straßen geöffnet und die Temperaturen mild sind. Tiere sind im Frühsommer besonders aktiv. Viele Parkstraßen sind etwa von November bis April geschlossen; im Winter ist der Park nur eingeschränkt per Snowcoach oder Schneemobil erreichbar."},{"question":"Wie reist man zum Yellowstone-Nationalpark an?","answer":"Es gibt keinen Flughafen direkt am Park. Üblich ist ein Flug ab Deutschland in die USA mit Inlandsanschluss nach Bozeman (BZN), Jackson Hole (JAC) oder Cody (COD). Von dort fährt man mit dem Mietwagen weiter; der Park selbst ist groß und nur per Auto sinnvoll zu erkunden."},{"question":"Braucht man im Yellowstone einen Mietwagen?","answer":"Ja, ein Mietwagen ist praktisch unverzichtbar. Der Park ist riesig, die Sehenswürdigkeiten liegen weit auseinander, und es gibt kaum öffentlichen Nahverkehr. Für die An- und Weiterreise im US-Westen ist ein Auto ohnehin ideal."},{"question":"Brauche ich für Yellowstone ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details dazu finden sich auf der USA-Seite."},{"question":"Was kostet der Eintritt in den Yellowstone-Nationalpark?","answer":"Für ein privates Fahrzeug gilt ein mehrtägiges Eintrittsticket. Wer mehrere US-Nationalparks besucht, fährt mit dem Jahrespass „America the Beautiful“ oft günstiger, der den Eintritt in alle Nationalparks abdeckt."},{"question":"Wo übernachtet man am besten?","answer":"Im Park gibt es historische Lodges und Campgrounds, die früh ausgebucht sind und lange im Voraus gebucht werden müssen. Alternativen bieten die Gateway-Towns wie West Yellowstone, Gardiner, Cooke City oder Jackson südlich des Parks."},{"question":"Wie verhält man sich gegenüber Wildtieren?","answer":"Yellowstone ist Wildnis mit freilebenden Tieren. Man muss großen Abstand halten – mindestens rund 91 Meter zu Bären und Wölfen sowie 23 Meter zu Bisons, Wapitis und anderen Tieren. Bärenspray wird empfohlen, und Tiere dürfen niemals gefüttert werden."},{"question":"Ist Yellowstone für Familien geeignet?","answer":"Ja, der Park ist ein großartiges Familienziel. Geysire, Tierbeobachtungen, einfache Boardwalk-Wege und das Junior-Ranger-Programm begeistern Kinder. Wichtig sind feste Wege, Sicherheitsabstand zu Tieren und Vorsicht an den heißen Quellen."},{"question":"Sollte man Yellowstone mit dem Grand-Teton-Nationalpark kombinieren?","answer":"Unbedingt. Der Grand-Teton-Nationalpark grenzt direkt im Süden an und beeindruckt mit seiner schroffen Bergkette und Seen. Beide Parks lassen sich über den John D. Rockefeller Jr. Memorial Parkway bequem verbinden."},{"question":"Muss man mit Höhe und wechselndem Wetter rechnen?","answer":"Ja, große Teile des Parks liegen auf über 2.000 Metern Höhe. Das Wetter kann schnell umschlagen, und selbst im Sommer sind kühle Nächte oder Schnee möglich. Wetterfeste Kleidung im Zwiebellook ist ratsam."},{"question":"Wie viele Tage sollte man für Yellowstone einplanen?","answer":"Für die wichtigsten Highlights sollte man mindestens 3 Tage einplanen, besser 4 bis 5, um Geysire, Wasserfälle und Tierbeobachtung in Ruhe zu erleben. In Kombination mit Grand Teton lohnt sich entsprechend mehr Zeit."}]$j$::jsonb, $t$Yellowstone-Nationalpark: Geysire, Tierwelt & beste Reisezeit$t$, $t$Dein Besuch im Yellowstone-Nationalpark: Old Faithful, die Grand Prismatic Spring, Wasserfälle und Wildtiere wie Bisons und Bären. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Yellowstone Reise buchen, Flug nach Bozeman oder Jackson Hole, Hotel West Yellowstone oder Jackson, Mietwagen USA-Westen, Yellowstone Touren und Wildlife-Safaris, Rundreise Nationalparks USA$t$, true, $j$["grand-teton","grand-canyon","yosemite"]$j$::jsonb, ARRAY[$t$Yellowstone-Nationalpark$t$,$t$Wyoming$t$,$t$Old Faithful$t$,$t$Grand Prismatic Spring$t$,$t$Mammoth Hot Springs$t$,$t$Norris Geyser Basin$t$,$t$Grand Canyon of the Yellowstone$t$,$t$Lower Falls$t$,$t$Lamar Valley$t$,$t$Hayden Valley$t$,$t$Yellowstone Lake$t$,$t$Bisons$t$,$t$Grizzlybären$t$,$t$Grand-Teton-Nationalpark$t$,$t$Bozeman$t$,$t$Jackson Hole$t$]::text[], $t$Der Yellowstone-Nationalpark im US-Westen (überwiegend Wyoming) ist der älteste Nationalpark der Welt und liegt auf einem Supervulkan, der seine einzigartige geothermale Landschaft speist. Berühmt ist er für Geysire wie Old Faithful, die regenbogenfarbene Grand Prismatic Spring, den Grand Canyon of the Yellowstone und seine reiche Tierwelt mit Bisons, Bären und Wölfen. Er eignet sich ideal als Höhepunkt eines USA-Westen-Roadtrips, am besten von Juni bis September; für die Einreise gelten die USA-Bestimmungen mit elektronischem Reisepass und ESTA.$t$, $t$Der Yellowstone-Nationalpark ist der älteste Nationalpark der Welt mit Geysiren wie Old Faithful, heißen Quellen, Wasserfällen und Wildtieren wie Bisons und Bären, am besten von Juni bis September.$t$, $t$https://www.apearound.de/reiseziele/yellowstone$t$, $t$/images/destinations/yellowstone.jpg$t$, $t$/images/destinations/yellowstone.jpg$t$, $t$Yellowstone-Nationalpark: Geysire, Tierwelt & beste Reisezeit$t$, $t$Dein Besuch im Yellowstone-Nationalpark: Old Faithful, die Grand Prismatic Spring, Wasserfälle und Wildtiere wie Bisons und Bären. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$Yellowstone-Nationalpark: Geysire, Tierwelt & beste Reisezeit$t$, $t$Dein Besuch im Yellowstone-Nationalpark: Old Faithful, die Grand Prismatic Spring, Wasserfälle und Wildtiere wie Bisons und Bären. Beste Reisezeit, Anreise, Tipps und Highlights im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Yosemite-Nationalpark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Yosemite-Nationalpark$t$, $t$yosemite$t$, $t$Vereinigte Staaten (USA)$t$, $t$Kalifornien (Sierra Nevada)$t$, $t$Nordamerika$t$, $t$/images/destinations/yosemite-hero.jpg$t$, $t$Spektakulärer Nationalpark in Kaliforniens Sierra Nevada mit gewaltigen Granitfelsen wie El Capitan und Half Dome, tosenden Wasserfällen und uralten Mammutbäumen.$t$, $t$Der Yosemite-Nationalpark in der kalifornischen Sierra Nevada zählt zu den eindrucksvollsten Naturlandschaften der Welt und ist UNESCO-Welterbe. Berühmt ist der Park für seine gewaltigen Granitformationen: Der senkrechte Monolith El Capitan gilt als Mekka der Kletterer, der markante Half Dome ist das Wahrzeichen des Parks. Im Herzen liegt das Yosemite Valley, über das die Yosemite Falls – die höchsten Wasserfälle Nordamerikas – in die Tiefe stürzen, ergänzt durch den zarten Bridalveil Fall. Vom Aussichtspunkt Glacier Point und vom klassischen Tunnel View bieten sich grandiose Panoramen über das Tal. In der Mariposa Grove ragen jahrtausendealte Riesenmammutbäume in den Himmel, und über die hochalpine Tioga Road erreicht man die weiten Tuolumne Meadows. Die Wasserfälle sind im Frühsommer durch die Schneeschmelze am eindrucksvollsten. Yosemite eignet sich perfekt als Höhepunkt eines Kalifornien-Roadtrips und ist ein Traumziel für Natur-, Wander-, Kletter- und Fotoreisen.$t$, $t$Der Yosemite-Nationalpark in Kaliforniens Sierra Nevada ist UNESCO-Welterbe und berühmt für die Granitfelsen El Capitan und Half Dome, die Yosemite Falls, das Yosemite Valley und die Mammutbäume der Mariposa Grove. Er eignet sich ideal als Höhepunkt eines Kalifornien-Roadtrips und für Natur- und Wanderreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Mai bis September/Oktober; die Wasserfälle sind im Frühsommer (Mai bis Juni) durch die Schneeschmelze am stärksten. Hochlagen wie die Tioga Road und Glacier Point sind meist nur von etwa Juni bis Oktober/November geöffnet.$t$, $t$2 bis 4 Tage, oft als Teil eines Kalifornien-Roadtrips$t$, ARRAY[$t$Naturreise$t$,$t$Nationalparks$t$,$t$Roadtrip$t$,$t$Wandern$t$,$t$Klettern$t$,$t$Fotoreise$t$,$t$Familien$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch","flightTime":"Kein Direktflug zum Park; ab Deutschland ca. 11 bis 12 Stunden in die USA plus Anschluss/Fahrt. Nächste Flughäfen: San Francisco (SFO, rund 3,5 bis 4 Stunden Fahrt) und Fresno (FAT, rund 2,5 Stunden)","timezone":"Pacific Time (UTC−8; im Sommer UTC−7), rund neun Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"Mai bis September"}$j$::jsonb, $j$["El Capitan – gewaltiger Granitmonolith und weltberühmtes Kletterziel","Half Dome – das markante Wahrzeichen des Parks","Yosemite Falls – die höchsten Wasserfälle Nordamerikas","Glacier Point – spektakulärer Aussichtspunkt über das Tal und auf Half Dome","Tunnel View – der klassische Postkartenblick ins Yosemite Valley","Mariposa Grove – jahrtausendealte Riesenmammutbäume (Sequoias)","Bridalveil Fall – markanter Wasserfall am Eingang des Tals","Tioga Road und Tuolumne Meadows – hochalpine Landschaft im Osten des Parks"]$j$::jsonb, $j$["Die Wasserfälle sind im Mai und Juni durch die Schneeschmelze am eindrucksvollsten; im Spätsommer führen einige deutlich weniger oder kein Wasser.","In der Hochsaison kann ein Reservierungssystem (Timed-Entry) für die Einfahrt gelten – die aktuellen Regeln unbedingt vorab auf nps.gov prüfen.","Unterkünfte im Tal sind sehr begehrt und müssen Monate im Voraus gebucht werden; günstigere Alternativen bieten Gateway-Towns wie Mariposa, Oakhurst, El Portal oder Groveland.","Lebensmittel gehören wegen der Bären in die bereitgestellten Bear Boxes und niemals über Nacht ins Auto; für den Aufstieg zum Half Dome ist ein Permit per Verlosung nötig."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für den Yosemite-Nationalpark?","answer":"Am eindrucksvollsten sind die Wasserfälle im Frühsommer (Mai bis Juni) während der Schneeschmelze. Für vollen Zugang inklusive Hochlagen wie der Tioga Road und Glacier Point eignen sich die Monate Juni bis Oktober. Im Winter ist das Tal zugänglich, viele Hochstraßen sind jedoch gesperrt."},{"question":"Braucht man eine Reservierung für die Einfahrt nach Yosemite?","answer":"In den letzten Jahren galt zu Stoßzeiten ein Reservierungssystem mit Timed-Entry für die Einfahrt. Ob und wann dies aktuell gilt, ändert sich jährlich, daher sollte man die offiziellen Regelungen vor der Reise unbedingt auf der Parkwebseite nps.gov prüfen."},{"question":"Wie reist man zum Yosemite-Nationalpark an?","answer":"Es gibt keinen Flughafen direkt am Park. Üblich ist ein Flug in die USA mit Ziel San Francisco (rund 3,5 bis 4 Stunden Fahrt) oder Fresno (rund 2,5 Stunden). Von dort fährt man mit dem Mietwagen weiter, oft im Rahmen eines Kalifornien-Roadtrips."},{"question":"Braucht man in Yosemite einen Mietwagen?","answer":"Für die An- und Weiterreise ist ein Mietwagen sehr empfehlenswert, da der Park abgelegen liegt. Im Yosemite Valley selbst gibt es in der Hauptsaison kostenlose Shuttlebusse, mit denen man die Hauptattraktionen autofrei erreichen kann."},{"question":"Brauche ich für Yosemite ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Was kostet der Eintritt in den Yosemite-Nationalpark?","answer":"Für ein privates Fahrzeug gilt ein mehrtägiges Eintrittsticket. Wer mehrere US-Nationalparks besucht, fährt mit dem Jahrespass „America the Beautiful“ oft günstiger, der den Eintritt in alle Nationalparks abdeckt."},{"question":"Wo übernachtet man am besten?","answer":"Im Park gibt es Lodges und Campgrounds, etwa im Yosemite Valley, die früh ausgebucht sind und lange im Voraus gebucht werden müssen. Alternativen bieten die Gateway-Towns wie Mariposa, Oakhurst, El Portal und Groveland."},{"question":"Wie besteigt man den Half Dome?","answer":"Der berühmte Aufstieg zum Half Dome mit seinen Stahlseilen erfordert ein spezielles Permit, das über eine Verlosung vergeben wird. Es handelt sich um eine lange, anspruchsvolle Wanderung, die gute Kondition und Trittsicherheit voraussetzt."},{"question":"Muss man im Yosemite mit Bären rechnen?","answer":"Ja, im Park leben Schwarzbären. Lebensmittel und duftende Gegenstände müssen in den bereitgestellten Bear Boxes verstaut werden und dürfen nicht im Auto bleiben. Bei Begegnungen hält man Abstand und füttert die Tiere niemals."},{"question":"Ist Yosemite für Familien geeignet?","answer":"Ja, der Park ist sehr familienfreundlich. Leichte Talwanderungen, Wasserfälle, das Shuttlesystem, Badestellen am Merced River und das Junior-Ranger-Programm sorgen für Abwechslung. Auf Sicherheit an Flüssen und Aussichtspunkten ist zu achten."},{"question":"Wie viele Tage sollte man für Yosemite einplanen?","answer":"Für die wichtigsten Highlights im Tal reichen 2 Tage, besser sind 3 bis 4 Tage, um auch Glacier Point, die Mariposa Grove und das Hochland entlang der Tioga Road zu erleben."}]$j$::jsonb, $t$Yosemite-Nationalpark: El Capitan, Wasserfälle & beste Reisezeit$t$, $t$Dein Besuch im Yosemite-Nationalpark: El Capitan, Half Dome, die Yosemite Falls und uralte Mammutbäume. Beste Reisezeit, Anreise, Reservierung, Tipps und Highlights im Überblick.$t$, $t$Yosemite Reise buchen, Flug nach San Francisco, Mietwagen Kalifornien, Hotel Mariposa oder Oakhurst, Yosemite Touren und Wanderungen, Rundreise Kalifornien Nationalparks$t$, true, $j$["yellowstone","grand-canyon","sequoia"]$j$::jsonb, ARRAY[$t$Yosemite-Nationalpark$t$,$t$Kalifornien$t$,$t$Sierra Nevada$t$,$t$El Capitan$t$,$t$Half Dome$t$,$t$Yosemite Falls$t$,$t$Yosemite Valley$t$,$t$Glacier Point$t$,$t$Tunnel View$t$,$t$Bridalveil Fall$t$,$t$Mariposa Grove$t$,$t$Mammutbäume$t$,$t$Tioga Road$t$,$t$Tuolumne Meadows$t$,$t$San Francisco$t$,$t$Merced River$t$]::text[], $t$Der Yosemite-Nationalpark in Kaliforniens Sierra Nevada ist UNESCO-Welterbe und berühmt für seine gewaltigen Granitfelsen El Capitan und Half Dome, die Yosemite Falls als höchste Wasserfälle Nordamerikas, das Yosemite Valley und die jahrtausendealten Mammutbäume der Mariposa Grove. Er eignet sich ideal als Höhepunkt eines Kalifornien-Roadtrips, am besten von Mai bis Oktober, wobei die Wasserfälle im Frühsommer am eindrucksvollsten sind. Für die Einreise gelten die USA-Bestimmungen mit elektronischem Reisepass und ESTA.$t$, $t$Der Yosemite-Nationalpark in Kalifornien begeistert mit den Granitfelsen El Capitan und Half Dome, den Yosemite Falls und Mammutbäumen, am besten von Mai bis Oktober.$t$, $t$https://www.apearound.de/reiseziele/yosemite$t$, $t$/images/destinations/yosemite.jpg$t$, $t$/images/destinations/yosemite.jpg$t$, $t$Yosemite-Nationalpark: El Capitan, Wasserfälle & beste Reisezeit$t$, $t$Dein Besuch im Yosemite-Nationalpark: El Capitan, Half Dome, die Yosemite Falls und uralte Mammutbäume. Beste Reisezeit, Anreise, Reservierung, Tipps und Highlights im Überblick.$t$, $t$Yosemite-Nationalpark: El Capitan, Wasserfälle & beste Reisezeit$t$, $t$Dein Besuch im Yosemite-Nationalpark: El Capitan, Half Dome, die Yosemite Falls und uralte Mammutbäume. Beste Reisezeit, Anreise, Reservierung, Tipps und Highlights im Überblick.$t$, $t$draft$t$)
ON CONFLICT (slug) DO NOTHING;

-- Zion-Nationalpark
INSERT INTO public.destinations (name, slug, country, region, continent, hero_image, short_description, long_description, ai_summary, best_travel_time, ideal_duration, travel_type, quick_facts, highlights, insider_tips, faq, seo_title, seo_description, affiliate_search_intent, car_rental_recommended, similar_destinations, llmo_entities, llmo_answer_block, llmo_quick_answer, canonical_url, open_graph_image, twitter_image, open_graph_title, open_graph_description, twitter_title, twitter_description, status)
VALUES ($t$Zion-Nationalpark$t$, $t$zion$t$, $t$Vereinigte Staaten (USA)$t$, $t$Utah (USA-Südwesten)$t$, $t$Nordamerika$t$, $t$/images/destinations/zion-hero.jpg$t$, $t$Spektakulärer Nationalpark in Utah mit gewaltigen roten Sandsteinwänden, der engen Flussschlucht The Narrows und der berühmten Steilwanderung Angels Landing.$t$, $t$Der Zion-Nationalpark im Süden Utahs ist einer der eindrucksvollsten Parks des amerikanischen Südwestens und ein Paradies für Wanderer und Naturliebhaber. Im Herzen liegt der Zion Canyon, eine tiefe Schlucht, deren gewaltige Sandsteinwände in leuchtendem Rot, Orange und Cremeweiß bis zu rund 800 Meter aufragen, durchflossen vom Virgin River. Zu den berühmtesten Erlebnissen zählt die ausgesetzte Steilwanderung Angels Landing, die über einen schmalen Grat mit Sicherungsketten zu einem atemberaubenden Aussichtspunkt führt und ein Permit erfordert. Ein weiteres Highlight sind The Narrows, wo man durch den Fluss zwischen den engsten, hoch aufragenden Felswänden des Parks wandert. Sanftere Wege wie die Emerald Pools oder der Canyon Overlook Trail bieten ebenfalls grandiose Ausblicke. Über den spektakulären Zion-Mount Carmel Highway samt Tunnel erreicht man den östlichen Parkteil. Zion lässt sich ideal mit Bryce Canyon, dem Grand Canyon und Las Vegas zu einer Südwesten-Rundreise verbinden und ist ein Traumziel für Wander-, Natur- und Fotoreisen.$t$, $t$Der Zion-Nationalpark in Utah begeistert mit gewaltigen roten Sandsteinwänden, dem Zion Canyon, der Flusswanderung The Narrows und der berühmten Steilwanderung Angels Landing. Er eignet sich ideal als Teil eines Südwesten-Roadtrips und für Wander- und Naturreisen; für die Einreise gelten die USA-Bestimmungen mit ESTA.$t$, $t$Frühling (April bis Mai) und Herbst (September bis Oktober) mit mildem Wetter sind ideal. Der Sommer ist heiß und sehr voll, die Winter sind mild. Die Flusswanderung The Narrows ist meist im Spätfrühling bis Frühherbst am besten begehbar.$t$, $t$1 bis 3 Tage, oft als Teil eines Südwesten-Roadtrips$t$, ARRAY[$t$Naturreise$t$,$t$Nationalparks$t$,$t$Roadtrip$t$,$t$Wandern$t$,$t$Canyoning$t$,$t$Fotoreise$t$,$t$Abenteuer$t$]::text[], $j${"currency":"US-Dollar (USD)","language":"Englisch","flightTime":"Kein Direktflug zum Park; ab Deutschland ca. 11 bis 12 Stunden in die USA plus Anschluss/Fahrt. Nächste Flughäfen: Las Vegas (LAS, rund 2,5 bis 3 Stunden Fahrt) und St. George (SGU, rund 1 Stunde)","timezone":"Mountain Time (UTC−7; im Sommer UTC−6), rund acht Stunden hinter MEZ","visa":"Wie für die USA: kein Visum für Touristen (bis 90 Tage), aber elektronischer Reisepass und kostenpflichtige ESTA-Genehmigung erforderlich","bestMonths":"April bis Mai sowie September bis Oktober"}$j$::jsonb, $j$["Zion Canyon – die zentrale Schlucht mit gewaltigen roten Sandsteinwänden","Angels Landing – berühmte, ausgesetzte Steilwanderung mit Sicherungsketten (Permit nötig)","The Narrows – Wanderung durch den Virgin River zwischen engen Felswänden","Emerald Pools – grüne Wasserbecken und Wasserfälle auf leichteren Wegen","Canyon Overlook Trail – kurze Wanderung mit weitem Blick über den Canyon","Zion-Mount Carmel Highway und Tunnel – spektakuläre Panoramastraße","The Watchman und Court of the Patriarchs – markante Felsformationen","Kolob Canyons – ruhigerer, weniger besuchter Teil des Parks"]$j$::jsonb, $j$["Im Zion Canyon gilt in der Hauptsaison Shuttle-Pflicht: Private Fahrzeuge dürfen die Scenic Drive nicht befahren, der kostenlose Shuttlebus bringt einen zu allen Startpunkten.","Die berühmte Wanderung Angels Landing erfordert ein Permit, das über eine Verlosung vergeben wird; der ausgesetzte Grat mit Ketten ist nichts für Menschen mit Höhenangst.","Für The Narrows watet man durch den Fluss – Wasserstand und Strömung vorab prüfen, festes Schuhwerk und einen Wanderstock (vor Ort leihbar) nutzen und die Flash-Flood-Warnungen ernst nehmen.","Der Park ist sehr beliebt; früh anreisen und Zion gut mit Bryce Canyon, dem Grand Canyon und Las Vegas zu einer Rundreise kombinieren."]$j$::jsonb, $j$[{"question":"Wann ist die beste Reisezeit für den Zion-Nationalpark?","answer":"Am angenehmsten sind Frühling (April bis Mai) und Herbst (September bis Oktober) mit mildem Wetter und etwas weniger Andrang. Der Sommer ist heiß und sehr voll, die Winter sind mild und ruhig. The Narrows ist meist vom Spätfrühling bis Frühherbst am besten begehbar."},{"question":"Darf man mit dem eigenen Auto in den Zion Canyon fahren?","answer":"In der Hauptsaison nicht: Dann gilt im Zion Canyon Shuttle-Pflicht, und private Fahrzeuge dürfen die Scenic Drive nicht befahren. Der kostenlose Shuttlebus bringt Besucher zu allen wichtigen Startpunkten. Außerhalb der Saison ist die Zufahrt teils mit dem Auto möglich."},{"question":"Braucht man für Angels Landing ein Permit?","answer":"Ja, für den finalen, ausgesetzten Abschnitt von Angels Landing ist ein Permit erforderlich, das über eine Verlosung vergeben wird. Die Wanderung führt über einen schmalen Grat mit Sicherungsketten und ist anspruchsvoll sowie nichts für Menschen mit Höhenangst."},{"question":"Was sind The Narrows?","answer":"The Narrows ist eine berühmte Wanderung, bei der man durch den Virgin River zwischen den engsten und höchsten Felswänden des Parks watet. Wichtig sind passende Ausrüstung, die Prüfung von Wasserstand und Strömung sowie die Beachtung der Flash-Flood-Gefahr."},{"question":"Wie reist man zum Zion-Nationalpark an?","answer":"Es gibt keinen Flughafen direkt am Park. Üblich ist ein Flug in die USA mit Ziel Las Vegas (rund 2,5 bis 3 Stunden Fahrt) oder St. George (rund 1 Stunde). Von dort fährt man mit dem Mietwagen weiter, meist im Rahmen eines Südwesten-Roadtrips."},{"question":"Braucht man am Zion einen Mietwagen?","answer":"Für die Anreise ist ein Mietwagen sehr empfehlenswert, da der Park abgelegen liegt und oft Teil eines Roadtrips ist. Im Zion Canyon selbst bewegt man sich in der Hauptsaison mit dem kostenlosen Shuttlebus fort."},{"question":"Brauche ich für den Zion ein Visum?","answer":"Es gelten die Einreisebestimmungen der USA: Für touristische Aufenthalte bis 90 Tage ist kein Visum nötig, aber ein elektronischer Reisepass und eine vorab beantragte, kostenpflichtige ESTA-Genehmigung. Details finden sich auf der USA-Seite."},{"question":"Was kostet der Eintritt in den Zion-Nationalpark?","answer":"Für ein privates Fahrzeug gilt ein mehrtägiges Eintrittsticket. Wer mehrere US-Nationalparks besucht, fährt mit dem Jahrespass „America the Beautiful“ oft günstiger, der den Eintritt in alle Nationalparks abdeckt."},{"question":"Wo übernachtet man am besten?","answer":"Direkt am Parkeingang liegt der Ort Springdale mit zahlreichen Hotels, Lodges und Restaurants, von dem aus der Shuttle in den Park fährt. Im Park selbst gibt es die Zion Lodge sowie Campingplätze, die früh ausgebucht sind."},{"question":"Ist der Zion für Familien geeignet?","answer":"Ja, der Park ist familienfreundlich. Leichtere Wege wie der Riverside Walk, die Emerald Pools und das Shuttlesystem eignen sich gut für Kinder. Anspruchsvolle und ausgesetzte Touren wie Angels Landing sind dagegen nichts für kleine Kinder."},{"question":"Wie viele Tage sollte man für den Zion einplanen?","answer":"Für die wichtigsten Highlights reichen 1 bis 2 Tage. Wer mehrere Wanderungen wie Angels Landing und The Narrows unternehmen möchte, plant 2 bis 3 Tage ein, oft kombiniert mit weiteren Parks im Südwesten."}]$j$::jsonb, $t$Zion-Nationalpark: Angels Landing, The Narrows & beste Reisezeit$t$, $t$Dein Besuch im Zion-Nationalpark in Utah: rote Sandsteinwände, die Wanderung Angels Landing und die Flussschlucht The Narrows. Beste Reisezeit, Shuttle, Anreise, Tipps und Highlights im Überblick.$t$, $t$Zion Nationalpark Reise buchen, Flug nach Las Vegas, Mietwagen USA-Südwesten, Hotel Springdale, Zion Touren und Wanderungen, Rundreise Südwesten USA Nationalparks$t$, true, $j$["bryce-canyon","grand-canyon","monument-valley"]$j$::jsonb, ARRAY[$t$Zion-Nationalpark$t$,$t$Utah$t$,$t$Zion Canyon$t$,$t$Angels Landing$t$,$t$The Narrows$t$,$t$Virgin River$t$,$t$Emerald Pools$t$,$t$Canyon Overlook Trail$t$,$t$Zion-Mount Carmel Highway$t$,$t$The Watchman$t$,$t$Kolob Canyons$t$,$t$Springdale$t$,$t$Las Vegas$t$,$t$USA-Südwesten$t$]::text[], $t$Der Zion-Nationalpark in Utah begeistert mit gewaltigen roten Sandsteinwänden, dem zentralen Zion Canyon, der Flusswanderung The Narrows durch den Virgin River und der berühmten ausgesetzten Steilwanderung Angels Landing. Er eignet sich ideal als Teil eines Südwesten-Roadtrips, am besten im Frühling und Herbst, und im Zion Canyon gilt in der Hauptsaison Shuttle-Pflicht. Für die Einreise gelten die USA-Bestimmungen mit elektronischem Reisepass und ESTA.$t$, $t$Der Zion-Nationalpark in Utah begeistert mit roten Sandsteinwänden, der Flussschlucht The Narrows und der Steilwanderung Angels Landing, am besten im Frühling und Herbst.$t$, $t$https://www.apearound.de/reiseziele/zion$t$, $t$/images/destinations/zion.jpg$t$, $t$/images/destinations/zion.jpg$t$, $t$Zion-Nationalpark: Angels Landing, The Narrows & beste Reisezeit$t$, $t$Dein Besuch im Zion-Nationalpark in Utah: rote Sandsteinwände, die Wanderung Angels Landing und die Flussschlucht The Narrows. Beste Reisezeit, Shuttle, Anreise, Tipps und Highlights im Überblick.$t$, $t$Zion-Nationalpark: Angels Landing, The Narrows & beste Reisezeit$t$, $t$Dein Besuch im Zion-Nationalpark in Utah: rote Sandsteinwände, die Wanderung Angels Landing und die Flussschlucht The Narrows. Beste Reisezeit, Shuttle, Anreise, Tipps und Highlights im Überblick.$t$, $t$draft$t$)
